// Defensive destructure — this payload shape sometimes arrives with
// missing keys, so don't assume blog/otherPlatforms are always present
const input = $input.first().json;
const blogContent = input.blogContent || '';
const blog = input.blog || {};
const otherPlatforms = Array.isArray(input.otherPlatforms) ? input.otherPlatforms : [];
const blogUrl =
  blog['Published URL'] ||
  `https://dotlymaps.com/blog/${input.slug || blog.slug || ''}`;

// If there's nothing to build prompts for (this week's otherPlatforms is empty),
// emit a single skip marker so downstream nodes don't choke on 0 items
if (otherPlatforms.length === 0) {
  return [{
    json: {
      platform: 'NONE',
      skipped: true,
      reason: 'otherPlatforms array was empty for this week',
      weekOf: blog['Week of'] || null,
      weekTheme: blog['Theme'] || null,
      weekNumber: blog['Week Number'] || null
    }
  }];
}

const systemPrompt = `You are a senior content writer for Zenith Innovations, a Zoho consulting and business automation agency based in the UK. You have 12 years of experience writing B2B content for tech-savvy but time-poor business owners.

VOICE & PERSONALITY:
- You have opinions. State them. Don't hedge with "many businesses find that..." or "it depends"
- Write like a smart person talking to a colleague — not presenting at a conference
- Slightly impatient with overcomplicated solutions or obvious advice
- Confident without being arrogant. Direct without being cold.
- Contractions everywhere: you'll, it's, don't, we've, isn't, won't, they're
- Occasionally start sentences with But, And, Or — real writers do this

SENTENCE RHYTHM (critical for passing AI detection):
- Vary length aggressively. Short. Then a longer one that builds context before landing the point. Then short again.
- Never write three sentences in a row with the same structure
- One-sentence paragraphs are fine. Encouraged, even.
- Ask one rhetorical question per piece — it breaks rhythm naturally

STRICTLY BANNED WORDS & PHRASES:
- Furthermore, Moreover, Additionally, In conclusion, In summary
- Leverage, Delve into, Game-changer, Unlock, Empower, Streamline, Elevate
- "It's worth noting", "It's important to remember", "It goes without saying"
- "In today's fast-paced world", "In the digital age", "Now more than ever"
- "Let's dive in", "Let's explore", "Without further ado"
- "Certainly!", "Absolutely!", "Great question!"
- Any phrase that sounds like a listicle intro or motivational poster

AI PATTERN BREAKS (non-negotiable):
- Never write parallel bullets where every item starts with the same word structure
- Never make every paragraph 3–4 sentences — uniform length is the #1 AI detection signal
- Don't end with a motivational summary restating everything you just said
- Include one throwaway observation that isn't strictly necessary but feels human
- At least once, start a new thought with zero transition just start it
- Include mild skepticism toward the reader once assume they've seen this problem firsthand
- One moment of honesty that slightly undercuts your own point humans do this, AI doesn't
- Normal hyphens (-) are allowed when grammatically correct or part of a standard compound term.

PUNCTUATION HABITS:
- Don't use Em dashes to interrupt a thought — like this 
- Ellipsis when trailing off makes sense...
- Short punchy sentence after a colon: like this
- No random mid-paragraph bolding
- Don't add these -- hyphens anywhere, it make content clearly AI generated and we don't want that

BEFORE EVERY SENTENCE YOU WRITE, CHECK:
1. Would a real person actually write it this way?
2. Does this sentence sound like the one before it? If yes change it
3. Have I used any banned phrase? If yes cut it
4. Is every paragraph the same length? If yes break one or cut one short

Your AI detection score must be below 20%. This is not a suggestion.`;

return otherPlatforms.map(platform => {
  // Normalize the platform name so trailing spaces / case slips don't
  // silently fall through to the "no instructions" case
  const platformName = (platform['Platform'] || '').trim();
  const cta = platform['Call To Action'] || 'Book a free Zoho CRM consultation with Zenith Innovations.';

  let platformInstructions = '';

  if (platformName === 'LinkedIn Company') {
    platformInstructions = `Write a professional LinkedIn post for Zenith Innovations company page.
- Length: 150–300 words
- First line is the hook — one sentence, no context-setting, never start with "We"
- Start with the problem, the tension, or a surprising observation
- Short paragraphs — 1 to 3 sentences max per block
- End with this exact question: ${cta}
- Max 3 hashtags at the very end only
- No emojis`;
  }

  else if (platformName === 'Facebook') {
    platformInstructions = `Write a casual Facebook post for Zenith Innovations company page.
- Length: 100–200 words
- Open with something relatable — a frustration or a "you know that feeling when..." moment
- Don't open with the company name or "We"
- Warm but not gushing — like a knowledgeable friend sharing something useful
- 1–2 emojis maximum, placed naturally, never at the start of every line
- End with: ${cta}`;
  }

  else if (platformName === 'Twitter/X') {
    platformInstructions = `Write a Twitter/X thread of 5–6 tweets, numbered (1/6, 2/6 etc).
- Tweet 1: Hook only. One or two sentences. No "thread" announcement. No emoji. Just the hook.
- Tweets 2–4: Each one is a standalone insight — complete on its own, not a continuation
- Tweet 5: The honest or contrarian take — slightly challenges the obvious answer
- Tweet 6: Soft landing + blog link + CTA: ${cta} + 2–3 hashtags here only
- Max 280 characters per tweet — count carefully
- Vary tweet length — some one line, some three, never uniform`;
  }

  else if (platformName === 'CEO LinkedIn') {
    platformInstructions = `Write a personal LinkedIn post for the CEO of Zenith Innovations.
- Add this at the very top, outside the post: [CEO — Please review and personalise this. Change any detail that doesn't match your actual experience. The goal is for this to sound like you wrote it on a Tuesday morning, not like marketing wrote it.]
- Length: 150–250 words
- Do NOT start with the word "I" as the first word — known AI signal on LinkedIn
- Start with a specific moment, client conversation, or hard-won observation
- First person throughout — personal, opinion-led, never corporate
- One paragraph max for the insight. Don't over-explain.
- No hashtags — personal posts perform better without them
- No emojis
- End with a genuine question: ${cta}`;
  }

  else if (platformName === 'Zoho Forum') {
    platformInstructions = `Write a Zoho Community forum post for Zenith Innovations.
- Length: 100–150 words
- Open by naming the exact problem — the kind someone would type into a search bar at 11pm
- Never start with "Hi everyone", "Great question", or any forum cliché
- Give the actual answer — practical, specific, with real field names or navigation paths where relevant
- No sales pitch, not even a soft one
- End with: ${cta}`;
  }

  else {
    // Unknown platform name — fall back to a generic instruction set
    // rather than silently producing an empty/broken prompt
    platformInstructions = `Write a native-feeling social post for Zenith Innovations for the "${platformName || 'unspecified'}" platform.
- Length: 100–250 words
- Open with the problem or a relatable frustration, not the company name
- Match a tone appropriate to a general professional social platform
- End with: ${cta}`;
  }

  const userPrompt = `Repurpose this week's blog content for the platform specified below. Write something that feels native to that platform — not a blog excerpt with the formatting changed.

BLOG CONTEXT:
- Headline: ${blog['Headline'] || ''}
- Core Message: ${blog['Core Message'] || ''}
- Theme: ${blog['Theme'] || ''}

PLATFORM CONTEXT:
- Platform: ${platformName}
- Hook/Headline for this platform: ${platform['Headline'] || ''}
- Core message angle: ${platform['Core Message'] || ''}
- Key points to work from: ${platform['Key Points'] || ''}

PLATFORM REQUIREMENTS:
${platformInstructions}
Strict Rule for all content:
- No use of em dashes (—) in any content
Return only the post content. No intro, no label, no "here's the post", no commentary after.`;

  return {
    json: {
      platform: platformName,
      blogUrl,
      systemPrompt,
      userPrompt,
      weekOf: blog['Week of'] || null,
      weekTheme: blog['Theme'] || null,
      weekNumber: blog['Week Number'] || null
    }
  };
});

// ============================================================
// COLLECT ALL CONTENT
// ============================================================
//
// PURPOSE:
// - Collect final blog content
// - Collect generated social posts
// - Collect media
// - Preserve all existing blog metadata
//
// IMPORTANT UPDATE:
// The backlink model has moved from Gemini/OpenRouter-style
// "Insert Backlinks" to GPT Responses API "Insert Backlinks1".
//
// This code supports BOTH paths:
//
// 1. New GPT:
//    Insert Backlinks1
//    → output[0].content[0].text
//
// 2. Old Gemini/OpenRouter:
//    Insert Backlinks
//    → content.parts[0].text
//
// It also supports several generic fallback response shapes,
// making future model switching easier.
// ============================================================


// ------------------------------------------------------------
// BLOG META
// ------------------------------------------------------------

// Existing source remains Parse Blog.
// This preserves your current workflow behavior.
const blogData =
  $('Parse Blog').first().json || {};

const blog =
  blogData.blog || {};


// ============================================================
// HELPER: SAFELY GET VALUE
// ============================================================

function safeGet(fn, fallback = null) {
  try {
    const value = fn();

    return (
      value !== undefined &&
      value !== null &&
      value !== ''
    )
      ? value
      : fallback;

  } catch (error) {
    return fallback;
  }
}


// ============================================================
// HELPER: EXTRACT TEXT FROM ANY AI RESPONSE
// ============================================================
//
// Supports:
//
// A. GPT Responses API
//    output[0].content[0].text
//
// B. OpenAI Chat
//    choices[0].message.content
//
// C. Gemini
//    candidates[0].content.parts[0].text
//
// D. Existing custom Gemini/n8n shape
//    content.parts[0].text
//
// E. Claude-style
//    content[0].text
//
// F. Direct text fields
// ============================================================

function extractAIText(raw) {

  if (!raw || typeof raw !== 'object') {
    return '';
  }

  // ----------------------------------------------------------
  // 1. GPT Responses API
  // ----------------------------------------------------------

  const gptResponsesText =
    safeGet(() =>
      raw.output?.[0]?.content?.[0]?.text
    );

  if (typeof gptResponsesText === 'string' && gptResponsesText.trim()) {
    return gptResponsesText.trim();
  }


  // ----------------------------------------------------------
  // 2. OpenAI Chat Completions
  // ----------------------------------------------------------

  const openAIChatText =
    safeGet(() =>
      raw.choices?.[0]?.message?.content
    );

  if (typeof openAIChatText === 'string' && openAIChatText.trim()) {
    return openAIChatText.trim();
  }


  // ----------------------------------------------------------
  // 3. Existing Gemini / older Insert Backlinks format
  // ----------------------------------------------------------

  const geminiLegacyText =
    safeGet(() =>
      raw.content?.parts?.[0]?.text
    );

  if (typeof geminiLegacyText === 'string' && geminiLegacyText.trim()) {
    return geminiLegacyText.trim();
  }


  // ----------------------------------------------------------
  // 4. Gemini standard candidates format
  // ----------------------------------------------------------

  const geminiCandidatesText =
    safeGet(() =>
      raw.candidates?.[0]?.content?.parts?.[0]?.text
    );

  if (typeof geminiCandidatesText === 'string' && geminiCandidatesText.trim()) {
    return geminiCandidatesText.trim();
  }


  // ----------------------------------------------------------
  // 5. Claude / generic content[0].text
  // ----------------------------------------------------------

  const genericContentText =
    safeGet(() =>
      raw.content?.[0]?.text
    );

  if (typeof genericContentText === 'string' && genericContentText.trim()) {
    return genericContentText.trim();
  }


  // ----------------------------------------------------------
  // 6. Direct output string
  // ----------------------------------------------------------

  if (
    typeof raw.output === 'string' &&
    raw.output.trim()
  ) {
    return raw.output.trim();
  }


  // ----------------------------------------------------------
  // 7. Direct text
  // ----------------------------------------------------------

  if (
    typeof raw.text === 'string' &&
    raw.text.trim()
  ) {
    return raw.text.trim();
  }


  // ----------------------------------------------------------
  // 8. Direct content string
  // ----------------------------------------------------------

  if (
    typeof raw.content === 'string' &&
    raw.content.trim()
  ) {
    return raw.content.trim();
  }


  return '';
}


// ============================================================
// HELPER: GET OUTPUT FROM A NODE SAFELY
// ============================================================

function getNodeAIText(nodeName) {

  try {

    const nodeOutput =
      $(nodeName).first().json;

    return extractAIText(nodeOutput);

  } catch (error) {

    return '';
  }
}


// ============================================================
// EXTRACT FINAL BLOG CONTENT
// ============================================================
//
// PRIORITY:
//
// 1. Parse Backlinked Blog
//    This is preferred because it receives the validated/
//    normalized backlink result.
//
// 2. Insert Backlinks1
//    New GPT Responses API path.
//
// 3. Insert Backlinks
//    Legacy Gemini/OpenRouter path.
//
// This makes model switching easy.
// ============================================================

let blogContent = '';


// ------------------------------------------------------------
// UPDATE:
// Prefer final parsed/validated content when available.
// ------------------------------------------------------------

blogContent =
  safeGet(() =>
    $('Parse Backlinked Blog').first().json.blogContent
  , '');


// ------------------------------------------------------------
// NEW GPT BACKLINK NODE
// ------------------------------------------------------------

if (
  !blogContent ||
  typeof blogContent !== 'string'
) {

  blogContent =
    getNodeAIText(
      'Insert Backlinks1'
    );
}


// ------------------------------------------------------------
// OLD GEMINI / OPENROUTER BACKLINK NODE
// ------------------------------------------------------------

if (
  !blogContent ||
  typeof blogContent !== 'string'
) {

  blogContent =
    getNodeAIText(
      'Insert Backlinks'
    );
}


// ------------------------------------------------------------
// Final fallback
// ------------------------------------------------------------

if (
  !blogContent ||
  typeof blogContent !== 'string'
) {

  blogContent =
    'Backlinked content not found';
}


// ============================================================
// MEDIA ASSETS
// ============================================================

let mediaImages = [];
let mediaVideos = [];

try {

  const mediaAssetsItems =
    $('Media Assets').all();

  if (
    mediaAssetsItems &&
    mediaAssetsItems.length > 0
  ) {

    mediaAssetsItems.forEach(item => {

      const dataArray =
        item.json?.data ||
        item.data ||
        [];

      if (!Array.isArray(dataArray)) {
        return;
      }

      dataArray.forEach(asset => {

        const doc =
          asset.doc || asset;

        const mimeType =
          doc.mimeType || '';

        const isVideo =
          mimeType.startsWith('video/');

        const mediaEntry = {

          id:
            doc.id ||
            asset.mediaId ||
            null,

          url:
            doc.url ||
            asset.mediaUrl ||
            '',

          alt:
            doc.alt ||
            '',

          filename:
            doc.filename ||
            '',

          mimeType,

          filesize:
            doc.filesize ||
            0,

          width:
            doc.width ||
            null,

          height:
            doc.height ||
            null,

          thumbnailURL:
            doc.thumbnailURL ||
            doc.sizes?.thumbnail?.url ||
            '',

          type:
            isVideo
              ? 'video'
              : 'image'
        };

        if (isVideo) {
          mediaVideos.push(
            mediaEntry
          );
        } else {
          mediaImages.push(
            mediaEntry
          );
        }

      });

    });

  }

} catch (error) {

  // ----------------------------------------------------------
  // UPDATE:
  // Media is optional, so an unavailable Media Assets node
  // must never break the workflow.
  // ----------------------------------------------------------

  mediaImages = [];
  mediaVideos = [];
}


// ============================================================
// MEDIA RESPONSE ID
// ============================================================

const mediaId = safeGet(
  () =>
    $('Media Response IDs')
      .first()
      .json
      .mediaId,
  null
);


// ============================================================
// PLATFORM POSTS
// ============================================================
//
// These are produced by Parse Platform Posts.
// Existing behavior is preserved.
// ============================================================

let platformItems = [];

try {

  platformItems =
    $('Parse Platform Posts').all();

} catch (error) {

  platformItems = [];
}


// ------------------------------------------------------------
// Helper for platform content
// ------------------------------------------------------------

function getPlatformContent(
  platformName
) {

  const item =
    platformItems.find(
      item =>
        item.json?.platform === platformName
    );

  return (
    item?.json?.content ||
    'Not generated'
  );
}


const linkedin =
  getPlatformContent(
    'LinkedIn Company'
  );

const facebook =
  getPlatformContent(
    'Facebook'
  );

const twitter =
  getPlatformContent(
    'Twitter/X'
  );

const ceoLinkedin =
  getPlatformContent(
    'CEO LinkedIn'
  );

const zohoForum =
  getPlatformContent(
    'Zoho Forum'
  );


// ============================================================
// WEEK / CONTENT PLAN META
// ============================================================

const weekOf =
  blog['Week of'] ||
  null;

const weekTheme =
  blog['Theme'] ||
  null;

const weekNumber =
  blog['Week Number'] ||
  null;

const blogHeadline =
  blog['Headline'] ||
  blogData.title ||
  '';


// ============================================================
// BLOG METADATA
// ============================================================
//
// Existing behavior retained.
// ============================================================

const blogTitle =
  blogData.title ||
  '';

const blogSlug =
  blogData.slug ||
  '';

const blogExcerpt =
  blogData.excerpt ||
  '';

const quickAnswer =
  blogData.quickAnswer ||
  '';

const keyTakeaways =
  Array.isArray(blogData.keyTakeaways)
    ? blogData.keyTakeaways
    : [];

const faq =
  Array.isArray(blogData.faq)
    ? blogData.faq
    : [];

const focusKeyword =
  blog['Focus Keyword'] ||
  blogData.focusKeyword ||
  '';

const category =
  blog['Category'] ||
  blogData.category ||
  '';

const metaTitle =
  blogData.metaTitle ||
  '';

const metaDescription =
  blogData.metaDescription ||
  '';

const searchKeywords =
  Array.isArray(blogData.searchKeywords)
    ? blogData.searchKeywords
    : [];

const featuredVideo =
  blogData.featuredVideo ||
  '';

const wordCount =
  blogData.contentQuality?.wordCount ||
  0;

const readingTimeMinutes =
  blogData.contentQuality?.readingTimeMinutes ||
  0;


// ============================================================
// ADDITIONAL BACKLINK DEBUG
// ============================================================
//
// UPDATE:
// Makes it obvious which provider actually supplied the final
// content. Very useful when switching between Gemini/OpenRouter
// and GPT/free models.
// ============================================================

let blogContentSource =
  'none';

if (
  safeGet(() =>
    $('Parse Backlinked Blog')
      .first()
      .json
      .blogContent,
    ''
  )
) {

  blogContentSource =
    'Parse Backlinked Blog';

} else if (
  getNodeAIText(
    'Insert Backlinks1'
  )
) {

  blogContentSource =
    'Insert Backlinks1';

} else if (
  getNodeAIText(
    'Insert Backlinks'
  )
) {

  blogContentSource =
    'Insert Backlinks';
}


// ============================================================
// RETURN
// ============================================================

return {

  json: {

    // --------------------------------------------------------
    // Week / blog identifiers
    // --------------------------------------------------------

    weekOf,

    weekTheme,

    weekNumber,

    blogHeadline,


    // --------------------------------------------------------
    // Media
    // --------------------------------------------------------

    mediaId,

    mediaImages,

    mediaVideos,


    // --------------------------------------------------------
    // Final blog
    // --------------------------------------------------------

    blogContent,


    // --------------------------------------------------------
    // Social content
    // --------------------------------------------------------

    linkedin,

    facebook,

    twitter,

    ceoLinkedin,

    zohoForum,


    // --------------------------------------------------------
    // Blog metadata
    // --------------------------------------------------------

    blogTitle,

    blogSlug,

    blogExcerpt,

    quickAnswer,

    keyTakeaways,

    faq,

    focusKeyword,

    category,

    metaTitle,

    metaDescription,

    searchKeywords,

    featuredVideo,

    wordCount,

    readingTimeMinutes,


    // --------------------------------------------------------
    // Debug / provider information
    // --------------------------------------------------------

    _backlinkDebug: {

      contentSource:
        blogContentSource,

      contentFound:
        !!blogContent,

      contentLength:
        typeof blogContent === 'string'
          ? blogContent.length
          : 0,

      legacyGeminiAvailable:
        !!getNodeAIText(
          'Insert Backlinks'
        ),

      gptBacklinks1Available:
        !!getNodeAIText(
          'Insert Backlinks1'
        ),

      parsedBacklinkedBlogAvailable:
        !!safeGet(
          () =>
            $('Parse Backlinked Blog')
              .first()
              .json
              .blogContent,
          ''
        )
    }

  }

};

const {
  weekOf, weekTheme, weekNumber,
  blogHeadline, blogContent,
  linkedin, facebook, twitter, ceoLinkedin, zohoForum,
  blogTitle, blogSlug, blogExcerpt, quickAnswer,
  keyTakeaways, faq, focusKeyword, category,
  metaTitle, metaDescription, searchKeywords,
  featuredVideo, wordCount, readingTimeMinutes,
  mediaImages, mediaVideos
} = $input.first().json;

// ---- Helper: extract H2 headings for TOC ----
function extractHeadings(html) {
  const headings = [];
  const regex = /<h2[^>]*>([^<]+)<\/h2>/gi;
  let match;
  while ((match = regex.exec(html)) !== null) {
    headings.push(match[1].trim());
  }
  return headings;
}

// ---- Helper: format HTML content ----
function formatBlogContent(html) {
  if (!html) return '';
  let formatted = html;
  if (!formatted.includes('<p>') && !formatted.includes('<h2>')) {
    formatted = formatted
      .split('\n\n')
      .map(p => `<p style="margin:0 0 14px;">${p.trim()}</p>`)
      .join('');
  }
  formatted = formatted.replace(
    /<a /g,
    '<a style="color:#1a73e8; text-decoration:underline;" '
  );
  return formatted;
}

// ---- Build blog content with inline images ----
function buildContentWithMedia(html, images, video) {
  const featured = images.length > 0 ? images[0] : null;
  const otherImages = images.slice(1);

  const blocks = html.split(/(?=<h2[^>]*>)/g);
  let result = '';

  // Hero image
  if (featured) {
    const imgSrc = featured.thumbnailURL || featured.url;
    result += `
      <div style="text-align:center; margin:0 0 24px;">
        <img src="${imgSrc}" alt="${featured.alt || featured.filename}" style="max-width:100%; max-height:500px; border-radius:8px; border:1px solid #e0e7ef; height:auto;" loading="lazy" />
        ${featured.alt ? `<div style="font-size:12px; color:#888; margin-top:4px;">${featured.alt}</div>` : ''}
      </div>
    `;
  }

  let imgIndex = 0;
  let videoInserted = false;

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];
    result += block;

    if (block.match(/<h2[^>]*>/)) {
      const headingText = block.replace(/<[^>]+>/g, '').trim();
      let imageToInsert = null;

      // Map headings to images using alt text keywords
      if (headingText.includes('The Invisible Gap')) {
        imageToInsert = otherImages.find(img => img.alt && img.alt.includes('UI dashboard'));
      } else if (headingText.includes('The Gen Z Pivot')) {
        imageToInsert = otherImages.find(img => img.alt && img.alt.includes('annotated geographic map'));
      } else if (headingText.includes('Why Traditional SEO Fails')) {
        imageToInsert = otherImages.find(img => img.alt && img.alt.includes('process flow diagram'));
      } else if (headingText.includes('How DotlyMaps Visualizes')) {
        imageToInsert = otherImages.find(img => img.alt && img.alt.includes('annotated geographic map'));
        // Insert video here
        if (!videoInserted && video) {
          const videoSrc = video.thumbnailURL || '';
          result += `
            <div style="text-align:center; margin:16px 0 20px; background:#f0f5fb; padding:16px; border-radius:8px;">
              <div style="font-weight:bold; margin-bottom:8px; color:#1a3c5e;">🎥 Video Walkthrough</div>
              <a href="${video.url}" target="_blank" style="color:#1a73e8; display:inline-block; padding:8px 16px; background:#fff; border:1px solid #1a73e8; border-radius:4px; text-decoration:none;">▶ Watch Video</a>
              <div style="font-size:12px; color:#888; margin-top:6px;">${video.filename}</div>
              ${videoSrc ? `<img src="${videoSrc}" alt="${video.alt}" style="max-width:100%; max-height:200px; border-radius:4px; margin-top:8px;" loading="lazy" />` : ''}
            </div>
          `;
          videoInserted = true;
        }
      }

      if (!imageToInsert && imgIndex < otherImages.length) {
        imageToInsert = otherImages[imgIndex++];
      }

      if (imageToInsert) {
        const imgSrc = imageToInsert.thumbnailURL || imageToInsert.url;
        result += `
          <div style="text-align:center; margin:12px 0 16px;">
            <img src="${imgSrc}" alt="${imageToInsert.alt || imageToInsert.filename}" style="max-width:100%; max-height:300px; border-radius:6px; border:1px solid #e0e7ef; height:auto;" loading="lazy" />
            ${imageToInsert.alt ? `<div style="font-size:12px; color:#888; margin-top:4px;">${imageToInsert.alt}</div>` : ''}
          </div>
        `;
      }
    }
  }

  // If video wasn't inserted, append it at the end
  if (!videoInserted && video) {
    const videoSrc = video.thumbnailURL || '';
