// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function stripTags(html) {
  return (html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

// ------------------------------------------------------------
// Quick answer
// ------------------------------------------------------------

function extractQuickAnswer(html) {

  if (!html) {
    return '';
  }

  const match =
    html.match(
      /Quick answer:?\s*([^.<>]+[.!?]?)/i
    );

  if (match) {

    let answer =
      stripTags(match[1]);

    if (answer.length > 320) {
      answer =
        answer.slice(0, 317).trim() + '...';
    }

    return answer;
  }

  const paragraph =
    html.match(
      /<p[^>]*>([\s\S]*?)<\/p>/i
    );

  if (!paragraph) {
    return '';
  }

  const text =
    stripTags(paragraph[1]);

  const sentences =
    text.match(/[^.!?]+[.!?]+/g) ||
    [text];

  let answer =
    sentences
      .slice(0, 2)
      .join(' ')
      .trim();

  if (answer.length > 320) {
    answer =
      answer.slice(0, 317).trim() + '...';
  }

  return answer;
}

// ------------------------------------------------------------
// Key takeaways
// ------------------------------------------------------------

function extractKeyTakeaways(html) {

  if (!html) {
    return [];
  }

  const headingRe =
    /<h[2-4][^>]*>\s*[^<]*key\s*takeaways?[^<]*<\/h[2-4]>([\s\S]*?)(?=<h[1-4]|$)/i;

  const match =
    html.match(headingRe);

  if (!match) {
    return [];
  }

  const ulMatch =
    match[1].match(
      /<ul[^>]*>([\s\S]*?)<\/ul>/i
    );

  if (!ulMatch) {
    return [];
  }

  const liRe =
    /<li[^>]*>([\s\S]*?)<\/li>/gi;

  const items = [];

  let li;

  while ((li = liRe.exec(ulMatch[1]))) {

    const text =
      stripTags(li[1]);

    if (text) {
      items.push({
        text
      });
    }
  }

  return items;
}

// ------------------------------------------------------------
// FAQ
// ------------------------------------------------------------

function extractFaq(html) {

  if (!html) {
    return [];
  }

  const faqs = [];

  const headingRe =
    /<h[2-4][^>]*>([^<]*\?)\s*<\/h[2-4]>\s*<p[^>]*>([\s\S]*?)<\/p>/gi;

  let match;

  while (
    (match = headingRe.exec(html))
  ) {

    const question =
      stripTags(match[1]);

    let answer =
      stripTags(match[2]);

    if (answer.length > 400) {
      answer =
        answer.slice(0, 397).trim() + '...';
    }

    if (question && answer) {

      faqs.push({
        question,
        answer
      });
    }
  }

  return faqs;
}

// ------------------------------------------------------------
// Title
// ------------------------------------------------------------

function extractTitle(html) {

  if (!html) {
    return '';
  }

  const h1 =
    html.match(
      /<h1[^>]*>([^<]+)<\/h1>/i
    );

  if (h1) {
    return stripTags(h1[1]);
  }

  const h2 =
    html.match(
      /<h2[^>]*>([^<]+)<\/h2>/i
    );

  if (h2) {
    return stripTags(h2[1]);
  }

  return '';
}

// ------------------------------------------------------------
// Slug
// ------------------------------------------------------------

function extractSlug(title) {

  if (!title) {
    return '';
  }

  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// ------------------------------------------------------------
// Excerpt
// ------------------------------------------------------------

function extractExcerpt(
  html,
  maxLength = 160
) {

  if (!html) {
    return '';
  }

  const paragraph =
    html.match(
      /<p[^>]*>([\s\S]*?)<\/p>/i
    );

  if (!paragraph) {
    return '';
  }

  let excerpt =
    stripTags(paragraph[1]);

  if (excerpt.length > maxLength) {
    excerpt =
      excerpt
        .slice(0, maxLength - 3)
        .trim() + '...';
  }

  return excerpt;
}

// ------------------------------------------------------------
// Word count
// ------------------------------------------------------------

function countWords(html) {

  if (!html) {
    return 0;
  }

  const text =
    stripTags(html);

  return text
    .split(/\s+/)
    .filter(Boolean)
    .length;
}

// ------------------------------------------------------------
// Reading time
// ------------------------------------------------------------

function calculateReadingTime(
  words
) {
  return Math.max(
    1,
    Math.ceil(words / 200)
  );
}

// ------------------------------------------------------------
// Extract links
// ------------------------------------------------------------

function extractInternalLinks(html) {

  if (!html) {
    return [];
  }

  const links = [];

  const regex =
    /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;

  let match;

  while (
    (match = regex.exec(html))
  ) {

    const url =
      match[1];

    const anchor =
      stripTags(match[2]);

    links.push({
      url,
      anchor
    });
  }

  return links;
}

// ------------------------------------------------------------
// Validate dynamic required links
// ------------------------------------------------------------

function validateRequiredLinks(html) {

  const requiredLinks =
    $('Input for prompt')
      .first()
      .json
      .requiredLinks || [];

  const results =
    requiredLinks.map(link => {

      const count =
        html
          .split(link.url)
          .length - 1;

      return {
        url: link.url,
        suggestedAnchor:
          link.suggestedAnchor || null,
        count,
        valid:
          count === 1
      };
    });

  const missing =
    results.filter(
      item => item.count === 0
    );

  const duplicates =
    results.filter(
      item => item.count > 1
    );

  return {

    valid:
      results.every(
        item => item.count === 1
      ),

    allPresent:
      missing.length === 0,

    noDuplicates:
      duplicates.length === 0,

    required:
      results,

    missingUrls:
      missing.map(
        item => item.url
      ),

    duplicateUrls:
      duplicates.map(
        item => item.url
      )
  };
}

