function collectMediaDocs(nodeName) {
  const collected = [];
  const items = readAllItems(nodeName);

  const pushIfMedia = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    if (obj.mediaId || obj.doc || obj.id || obj.mediaUrl) {
      collected.push(obj);
    }
  };

  const walk = (node) => {
    if (!node) return;
    if (Array.isArray(node)) { node.forEach(walk); return; }
    if (typeof node !== 'object') return;
    if (Array.isArray(node.data))    { node.data.forEach(walk);    return; }
    if (Array.isArray(node.results)) { node.results.forEach(walk); return; }
    if (Array.isArray(node.items))   { node.items.forEach(walk);   return; }
    if (Array.isArray(node.media))   { node.media.forEach(walk);   return; }
    pushIfMedia(node);
  };

  items.forEach(walk);
  if (collected.length === 0) walk(readNode(nodeName));
  return collected;
}

function classifyMedia(item) {
  const doc = item?.doc || item || {};
  const alt = String(doc.alt || item?.alt || '').toLowerCase();
  const filename = String(doc.filename || item?.filename || '').toLowerCase();
  const haystack = `${alt} ${filename}`;

  if (/\bhero\b|\bfeatured\b/.test(haystack))                          return 'featured';
  if (/\bui[-\s]?screenshot\b|\bscreenshot\b|(^|\s)ui(\s|$)/.test(haystack)) return 'uiScreenshot';
  if (/\bannotated[-\s]?map\b|\bannotated\b/.test(haystack))          return 'annotatedMap';
  if (/\bdiagram\b/.test(haystack))                                   return 'diagram';
  if (/\bcompar/.test(haystack))                                      return 'comparison';
  return 'other';
}

