/**
 * n8n "Prepare renhanced Payload" Code node
 * Mode: Run Once for Each Item
 * Converts blog HTML -> Payload CMS Lexical JSON, and builds the full POST body.
 * UPDATED: Uses staticData.currentDraft as primary source, adds category, truncates metaTitle, preserves full searchKeywords and quickAnswer.
 */

const SEARCH_KEYWORDS_FIELD_TYPE = 'array';
const SITE_BASE_URL = 'https://dotlymaps.com';
const AUTHOR_FIELD_TYPE = 'single';
const AUTHOR_RELATION_TO = 'authors';
const DEFAULT_AUTHOR_ID = '6a5e038e8021f4b245462ab6';
const MEDIA_RELATION_TO = 'media';

// ---------- HTML entity decode ----------
function decodeEntities(str) {
  if (!str) return '';
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

// ---------- text node builder ----------
function makeText(text, formatBits) {
  return {
    type: 'text',
    text,
    format: formatBits || 0,
    detail: 0,
    mode: 'normal',
    style: '',
    version: 1
  };
}

// ---------- inline parser (bold/italic/code/link/br) ----------
function parseInline(html, formatBits) {
  formatBits = formatBits || 0;
  const nodes = [];
  const tagRe = /<(\/?)(strong|b|em|i|code|a|br)\b([^>]*)>/i;
  let remaining = html || '';
  let cursor = 0;

  while (cursor < remaining.length) {
    const rest = remaining.slice(cursor);
    const m = rest.match(tagRe);
    if (!m) {
      const text = decodeEntities(rest);
      if (text) nodes.push(makeText(text, formatBits));
      break;
    }
    const idx = m.index;
    if (idx > 0) {
      const text = decodeEntities(rest.slice(0, idx));
      if (text) nodes.push(makeText(text, formatBits));
    }
    const closing = m[1] === '/';
    const tagName = m[2].toLowerCase();
    const attrs = m[3] || '';
    cursor += idx + m[0].length;

    if (tagName === 'br') {
      nodes.push({ type: 'linebreak', version: 1 });
      continue;
    }

    if (!closing) {
      let innerFormatBits = formatBits;
      if (tagName === 'strong' || tagName === 'b') innerFormatBits |= 1;
      if (tagName === 'em' || tagName === 'i') innerFormatBits |= 2;
      if (tagName === 'code') innerFormatBits |= 16;

      if (tagName === 'a') {
        const hrefMatch = attrs.match(/href=["']([^"']+)["']/i);
        const targetMatch = attrs.match(/target=["']([^"']+)["']/i);
        const url = hrefMatch ? hrefMatch[1] : '';
        const newTab = targetMatch ? targetMatch[1] === '_blank' : false;
        const closeTagStr = '</a>';
        const closeIdx = remaining.indexOf(closeTagStr, cursor);
        const innerHtml = closeIdx === -1 ? remaining.slice(cursor) : remaining.slice(cursor, closeIdx);
        const innerNodes = parseInline(innerHtml, innerFormatBits);
        nodes.push({
          type: 'link',
          fields: { url, newTab, linkType: 'custom' },
          format: '',
          indent: 0,
          direction: 'ltr',
          version: 2,
          children: innerNodes.length ? innerNodes : [makeText(url, innerFormatBits)]
        });
        cursor = closeIdx === -1 ? remaining.length : closeIdx + closeTagStr.length;
        continue;
      }

      const closeTagStr = `</${tagName}>`;
      const closeIdx = remaining.indexOf(closeTagStr, cursor);
      const innerHtml = closeIdx === -1 ? remaining.slice(cursor) : remaining.slice(cursor, closeIdx);
      nodes.push(...parseInline(innerHtml, innerFormatBits));
      cursor = closeIdx === -1 ? remaining.length : closeIdx + closeTagStr.length;
    }
  }
  return nodes;
}

// ---------- find matching close tag ----------
function findMatchingClose(html, tag, startIdx) {
  const openRe = new RegExp(`<${tag}\\b[^>]*>`, 'gi');
  const closeRe = new RegExp(`</${tag}>`, 'gi');
  let depth = 1;
  let i = startIdx;
  while (depth > 0) {
    openRe.lastIndex = i;
    closeRe.lastIndex = i;
    const openMatch = openRe.exec(html);
    const closeMatch = closeRe.exec(html);
    if (!closeMatch) return html.length;
    if (openMatch && openMatch.index < closeMatch.index) {
      depth++;
      i = openMatch.index + openMatch[0].length;
    } else {
      depth--;
      i = closeMatch.index + closeMatch[0].length;
      if (depth === 0) return closeMatch.index;
    }
  }
  return i;
}

// ---------- split top-level block elements ----------
function splitBlocks(html) {
  const blocks = [];
  const blockTagPattern = /<(h[1-6]|p|ul|ol|blockquote|table)\b[^>]*>|<hr\s*\/?>/gi;
  let match;
  while ((match = blockTagPattern.exec(html))) {
    const tag = match[1] ? match[1].toLowerCase() : 'hr';
    if (tag === 'hr') {
      blocks.push({ tag: 'hr', inner: '' });
      blockTagPattern.lastIndex = match.index + match[0].length;
      continue;
    }
    const openEnd = match.index + match[0].length;
    const closeIdx = findMatchingClose(html, tag, openEnd);
    blocks.push({ tag, inner: html.slice(openEnd, closeIdx) });
    blockTagPattern.lastIndex = closeIdx + `</${tag}>`.length;
  }
  return blocks;
}

// ---------- list item parser ----------
function parseListItems(listInner) {
  const items = [];
  const liRe = /<li\b[^>]*>/gi;
  let match;
  while ((match = liRe.exec(listInner))) {
    const openEnd = match.index + match[0].length;
    const closeIdx = findMatchingClose(listInner, 'li', openEnd);
    const liInner = listInner.slice(openEnd, closeIdx);
    liRe.lastIndex = closeIdx;

    const nestedMatch = liInner.match(/<(ul|ol)\b[^>]*>/i);
    let ownText = liInner;
    let nestedNode = null;
    if (nestedMatch) {
      ownText = liInner.slice(0, nestedMatch.index);
      const nestedTag = nestedMatch[1].toLowerCase();
      const nestedOpenEnd = nestedMatch.index + nestedMatch[0].length;
      const nestedCloseIdx = findMatchingClose(liInner, nestedTag, nestedOpenEnd);
      nestedNode = buildListNode(nestedTag, liInner.slice(nestedOpenEnd, nestedCloseIdx));
    }

    const children = parseInline(ownText);
    const listItemNode = {
      type: 'listitem',
      children: children.length ? children : [makeText('', 0)],
      direction: 'ltr', format: '', indent: 0, version: 1,
      value: items.length + 1
    };

    items.push(listItemNode);
    if (nestedNode) {
      items.push({
        type: 'listitem',
        children: [nestedNode],
        direction: 'ltr', format: '', indent: 0, version: 1,
        value: items.length + 1
      });
    }
  }
  return items;
}

function buildListNode(tag, inner) {
  return {
    type: 'list',
    listType: tag === 'ol' ? 'number' : 'bullet',
    tag,
    start: 1,
    children: parseListItems(inner),
    direction: 'ltr', format: '', indent: 0, version: 1
  };
}

// ---------- table parser ----------
function parseTable(inner) {
  const rows = [];
  const rowRe = /<tr\b[^>]*>/gi;
  let match;
  while ((match = rowRe.exec(inner))) {
    const openEnd = match.index + match[0].length;
    const closeIdx = findMatchingClose(inner, 'tr', openEnd);
    const rowInner = inner.slice(openEnd, closeIdx);
    rowRe.lastIndex = closeIdx;

    const cells = [];
    const cellRe = /<(td|th)\b[^>]*>/gi;
    let cellMatch;
    while ((cellMatch = cellRe.exec(rowInner))) {
      const cTag = cellMatch[1].toLowerCase();
      const cOpenEnd = cellMatch.index + cellMatch[0].length;
      const cCloseIdx = findMatchingClose(rowInner, cTag, cOpenEnd);
      const cellInner = rowInner.slice(cOpenEnd, cCloseIdx);
      cellRe.lastIndex = cCloseIdx;
      cells.push({
        type: 'tablecell',
        headerState: cTag === 'th' ? 1 : 0,
        children: [{
          type: 'paragraph',
          children: parseInline(cellInner),
          direction: 'ltr', format: '', indent: 0, version: 1
        }],
        direction: 'ltr', format: '', indent: 0, version: 1
      });
    }
    rows.push({
      type: 'tablerow',
      children: cells,
      direction: 'ltr', format: '', indent: 0, version: 1
    });
  }
  return { type: 'table', children: rows, direction: 'ltr', format: '', indent: 0, version: 1 };
}

// ---------- build Lexical node for one block ----------
function buildBlockNode(block) {
  if (block.tag === 'hr') return { type: 'horizontalrule', version: 1 };

  if (/^h[1-6]$/.test(block.tag)) {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'heading', tag: block.tag, children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'p') {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'paragraph', children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'blockquote') {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'quote', children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'ul' || block.tag === 'ol') return buildListNode(block.tag, block.inner);
  if (block.tag === 'table') return parseTable(block.inner);

  const children = parseInline(block.inner);
  if (!children.length) return null;
  return { type: 'paragraph', children, direction: 'ltr', format: '', indent: 0, version: 1 };
}

// ---------- Build a Lexical upload (image/video) node WITH alt/caption ----------
function buildUploadNode(asset) {
  if (!asset || !asset.mediaId) return null;
  return {
    type: 'upload',
    relationTo: MEDIA_RELATION_TO,
    value: asset.mediaId,
    fields: {
      alt: asset.alt || '',
      caption: asset.alt || ''
    },
    format: '',
    version: 3
  };
}

// ---------- HTML → Lexical root (with optional in-body image/video injection) ----------
function htmlToLexical(html, inBodyAssets) {
  const cleaned = (html || '').replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
  const blocks = splitBlocks(cleaned);
  let children = blocks.map(buildBlockNode).filter(Boolean);

  const images = (inBodyAssets || []).map(buildUploadNode).filter(Boolean);

  if (images.length && children.length) {
    const headingIdxs = [];
    children.forEach((node, i) => {
      if (node.type === 'heading' && /^h[23]$/.test(node.tag)) headingIdxs.push(i);
    });

    const withImages = [];
    let imgPointer = 0;

    if (headingIdxs.length >= images.length) {
      const step = Math.max(1, Math.floor(headingIdxs.length / images.length));
      const anchorSet = new Set();
      for (let k = 0; k < images.length; k++) {
        const anchor = headingIdxs[Math.min(headingIdxs.length - 1, (k + 1) * step - 1)];
        anchorSet.add(anchor);
      }
      const anchors = [...anchorSet];

      children.forEach((node, i) => {
        withImages.push(node);
        if (anchors.includes(i) && imgPointer < images.length) {
          withImages.push(images[imgPointer++]);
        }
      });
      while (imgPointer < images.length) withImages.push(images[imgPointer++]);
    } else {
      const gap = Math.max(1, Math.floor(children.length / (images.length + 1)));
      children.forEach((node, i) => {
        withImages.push(node);
        if (i > 0 && i % gap === 0 && imgPointer < images.length) {
          withImages.push(images[imgPointer++]);
        }
      });
      while (imgPointer < images.length) withImages.push(images[imgPointer++]);
    }

    children = withImages;
  }

  return {
    root: {
      type: 'root',
      direction: 'ltr',
      format: '',
      indent: 0,
      version: 1,
      children: children.length
        ? children
        : [{ type: 'paragraph', children: [makeText('', 0)], direction: 'ltr', format: '', indent: 0, version: 1 }]
    }
  };
}

// ---------- helpers ----------
function pick(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}

function buildAuthorField(authorId) {
  const id = (authorId || '').trim();
  if (!id) return null;
  if (AUTHOR_FIELD_TYPE === 'polymorphic') return { relationTo: AUTHOR_RELATION_TO, value: id };
  if (AUTHOR_FIELD_TYPE === 'hasMany') return [id];
  return id;
}

function buildSearchKeywords(rawList) {
  const clean = (Array.isArray(rawList) ? rawList : [])
    .map(k => typeof k === 'string' ? k : (k?.keyword || k?.text || ''))
    .map(k => k.trim())
    .filter(Boolean);
  return SEARCH_KEYWORDS_FIELD_TYPE === 'array'
    ? clean.map(keyword => ({ keyword }))
    : clean;
}

