parameters.jsCode:
// ─────────────────────────────────────────────────────────────────────────────
// Node 1: Generate Multiple Image Prompts
// Source of truth: DotlyMaps BLOG_CONTENT_BRIEFS.md — Global Image Guidelines
//
// 5 Image types (from brief):
//   hero          → blog-{slug}-featured.webp       1200×630  OG + listing card
//   ui-screenshot → blog-{slug}-ui-{shot}.webp      1600×900  Proof of capability
//   annotated-map → blog-{slug}-map-{concept}.webp  1600×900  Territory/heat/routes
//   diagram       → blog-{slug}-diagram-{name}.webp 1400×900  Processes, planning
//   comparison    → blog-{slug}-compare.webp         1400×900  Vs / alternative posts only
// ─────────────────────────────────────────────────────────────────────────────

const blog     = $input.first().json;
const title    = blog.title    || '';
const slug     = blog.slug     || 'featured';
const excerpt  = blog.excerpt  || '';
const keyword  = blog.blog?.['Focus Keyword'] || '';
const category = (blog.blog?.['Category'] || blog.blog?.['category'] || 'tips').toLowerCase();
const angle    = (blog.blog?.['Angle'] || '').toLowerCase();
const theme    = (blog.blog?.['Theme'] || '').toLowerCase();

// Rich context from takeaways (first 3)
const themes = (blog.keyTakeaways || [])
  .map(k => k.text || k)
  .slice(0, 3)
  .join('. ');

// FAQ questions for prompt context
const faqSnippet = (blog.faq || [])
  .map(f => f.question)
  .slice(0, 2)
  .join('; ');

// Core message for the post
const coreMessage = blog.blog?.['Core Message'] || excerpt;

// Determine which optional image types apply
const isComparisonPost = category === 'company' ||
  angle.includes('commercial') ||
  title.toLowerCase().includes(' vs ');

// ── Define all image types ──────────────────────────────────────────────────

const imageTypes = [

  // 1. HERO / FEATURED  ─────────────────────────────────────────────────────
  //    Every post. OG card + listing thumbnail.
  {
    type:     'hero',
    filename: `blog-${slug}-featured.webp`,
    size:     '1200x630',
    alt:      `${title} — DotlyMaps interactive map view`,
    context: [
      `Hero / featured image for the blog post titled: "${title}".`,
      `This image will appear as the Open Graph card on social media and on the blog listing page.`,
      `It must immediately communicate the primary outcome for the buyer.`,
      `Core message: ${coreMessage}`,
      `Focus keyword: ${keyword}.`,
      `Show a professional B2B SaaS map interface with customer/account pins spread across a regional map,`,
      `color-coded data layers, and a clean modern dashboard chrome (nav bar, sidebar panel, minimal labels).`,
      `Mood: confident, data-driven, enterprise-grade. Color palette: deep navy #1a3c5e, teal accents, white UI surfaces.`
    ].join(' ')
  },

  // 2. PRODUCT UI SCREENSHOT  ──────────────────────────────────────────────
  //    Every post. Proof-of-capability shot.
  {
    type:     'ui-screenshot',
    filename: `blog-${slug}-ui-main.webp`,
    size:     '1600x900',
    alt:      `DotlyMaps ${keyword} dashboard interface`,
    context: [
      `Product UI screenshot image that proves DotlyMaps capability for: "${title}".`,
      `Show a realistic SaaS map dashboard at 1600×900 aspect ratio.`,
      `UI elements to include: interactive map with clustered account/contact pins,`,
      `a left or right sidebar with filter controls (pipeline stage, owner, deal amount),`,
      `color-coded pins grouped by status (open = blue, won = green, lost = red/muted),`,
      `and a top navigation bar with search and user avatar.`,
      `Visual context from post key points: ${themes}`,
      `FAQ questions this image supports: ${faqSnippet}`,
      `Clean minimal SaaS UI. No fake data labels. No logos. Brand palette: navy, teal, white.`
    ].join(' ')
  },

  // 3. ANNOTATED MAP  ──────────────────────────────────────────────────────
  //    Every post. Geographic insight: territory, heat, coverage gap, routes.
  {
    type:     'annotated-map',
    filename: `blog-${slug}-map-coverage.webp`,
    size:     '1600x900',
    alt:      `Annotated map showing ${keyword} geographic coverage and territory patterns`,
    context: [
      `Annotated geographic map image for the blog: "${title}".`,
      `Show a real-looking business map with one or more of these visual layers:`,
      `(a) customer/account pins clustered in dense metro areas with sparse rural areas visible,`,
      `(b) colored polygon territory overlays with account pins inside each territory,`,
      `(c) a heat / density gradient showing revenue concentration over a metro region,`,
      `(d) route polylines connecting sequential stop locations on a regional map.`,
      `The map should visually demonstrate a key business insight from the post.`,
      `Post focus: ${keyword}. Themes illustrated: ${themes}`,
      `Base map style: light gray street map with colored overlay layers on top.`,
      `Color palette for overlays: teal #00b4d8, navy #1a3c5e, amber #f4a261 for contrast zones.`,
      `No street text visible. No watermarks. Professional cartographic quality.`
    ].join(' ')
  },

  // 4. DIAGRAM / FRAMEWORK  ─────────────────────────────────────────────────
  //    Every post. Process steps, planning framework, workflow.
  {
    type:     'diagram',
    filename: `blog-${slug}-diagram-process.webp`,
    size:     '1400x900',
    alt:      `${keyword} process diagram: step-by-step workflow framework`,
    context: [
      `Process diagram / framework infographic image for: "${title}".`,
      `The blog explains a structured workflow or planning model the reader must follow.`,
      `Show a clean B2B infographic with 4–6 connected stages, left-to-right or top-to-bottom flow,`,
      `rounded rectangle stage blocks connected by arrows, small icon per stage,`,
      `alternating fill colors (navy block → teal block → lighter accent block).`,
      `Stages / steps implied by the post: ${themes}`,
      `Focus keyword context: ${keyword}.`,
      `Style: modern flat design, no heavy drop shadows, no gradients, white background.`,
      `No text labels inside the boxes. Icon-only stage indicators. Professional B2B infographic quality.`
    ].join(' ')
  },

  // 5. COMPARISON GRAPHIC  ─────────────────────────────────────────────────
  //    Only for category=company posts or commercial/vs posts.
  ...(isComparisonPost ? [{
    type:     'comparison',
    filename: `blog-${slug}-compare.webp`,
    size:     '1400x900',
    alt:      `${keyword}: comparison graphic showing key differences between approaches`,
    context: [
      `Comparison graphic image for the commercial / competitive blog: "${title}".`,
      `Show a clean two-column or three-column visual layout comparing different tool approaches or buyer personas.`,
      `Do NOT use real brand names, logos, or recognizable UI chrome from specific companies.`,
      `Use abstract icon-based column headers (e.g., legacy icon vs modern cloud icon vs AI icon).`,
      `Rows represent evaluation criteria (deploy speed, CRM sync, learning curve, use cases).`,
      `The rightmost or highlighted column should appear more modern and capable (without being smug).`,
      `Post context: ${coreMessage}`,
      `Color palette: navy header row, teal highlight for recommended column, light gray alternating rows, white background.`,
      `Style: clean B2B comparison table infographic, enterprise SaaS aesthetic. No text labels.`
    ].join(' ')
  }] : [])

];

// ── Emit one item per image type ────────────────────────────────────────────
return imageTypes.map((img, idx) => ({
  json: {
    ...blog,

    // Image metadata
    imageType:       img.type,
    imageFilename:   img.filename,
    imageSize:       img.size,
    imageAlt:        img.alt,
    imageContext:    img.context,
    totalImages:     imageTypes.length,
    currentIndex:    idx,

    // Convenience fields for downstream nodes
    blogTitle:       title,
    blogSlug:        slug,
    blogExcerpt:     excerpt,
    focusKeyword:    keyword,
    blogCategory:    category,
    blogThemes:      themes,
    blogCoreMessage: coreMessage,
    isComparisonPost
  }
}));

// ─────────────────────────────────────────────────────────────────────────────
// Node 3: Parse Image Prompt
// Extracts AI-generated imageType, imagePrompt + negativePrompt from OpenRouter response.
// Falls back to brand-consistent defaults for all 5 DotlyMaps image types.
// Mode: Run Once for Each Item
// ─────────────────────────────────────────────────────────────────────────────

const raw      = $input.item.json;
const blogData = $input.item.json;

// ── 1. Extract raw content from OpenRouter response ──────────────────────────
let rawContent = '';

if (raw?.choices?.[0]?.message?.content) {
  rawContent = raw.choices[0].message.content;
} else if (raw?.output?.[0]?.content?.[0]?.text) {
  rawContent = raw.output[0].content[0].text;
} else if (typeof raw?.text === 'string') {
  rawContent = raw.text;
}

// ── 2. Clean and parse JSON ───────────────────────────────────────────────────
let imagePrompt    = '';
let negativePrompt = '';
let imageType      = '';

try {
  const cleaned = rawContent
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .replace(/undefined\??$/, '')
    .trim();

  const parsed = JSON.parse(cleaned);

  // Extract all three fields
  imagePrompt    = parsed.imagePrompt    || parsed.prompt || '';
  negativePrompt = parsed.negativePrompt || parsed.negative || '';
  imageType      = parsed.imageType      || '';

  // Remove the [imageType] prefix from the prompt if present
  if (imagePrompt) {
    const typeMatch = imagePrompt.match(/^\[([^\]]+)\]\s*/);
    if (typeMatch) {
      if (!imageType) imageType = typeMatch[1];
      imagePrompt = imagePrompt.replace(/^\[([^\]]+)\]\s*/, '');
    }
  }

} catch (e) {
  // Regex fallback if JSON parse fails
  const promptMatch   = rawContent.match(/"imagePrompt"\s*:\s*"([^"]+)"/);
  const negativeMatch = rawContent.match(/"negativePrompt"\s*:\s*"([^"]+)"/);
  const typeMatch     = rawContent.match(/"imageType"\s*:\s*"([^"]+)"/);

  imagePrompt    = promptMatch   ? promptMatch[1]   : '';
  negativePrompt = negativeMatch ? negativeMatch[1] : '';
  imageType      = typeMatch     ? typeMatch[1]     : '';

  // Clean [type] prefix from prompt if extracted separately
  if (imagePrompt) {
    const prefixMatch = imagePrompt.match(/^\[([^\]]+)\]\s*/);
    if (prefixMatch) {
      if (!imageType) imageType = prefixMatch[1];
      imagePrompt = imagePrompt.replace(/^\[([^\]]+)\]\s*/, '');
    }
  }
}

// ── 3. Determine image type ──────────────────────────────────────────────────
// Priority: 1. Parsed from AI response, 2. From blogData, 3. Default to 'hero'
const finalType = imageType || blogData.imageType || 'hero';

// ── 4. Fallback prompts for all 5 DotlyMaps image types ──────────────────────
const title   = blogData.blogTitle    || blogData.title || 'DotlyMaps blog';
const keyword = blogData.focusKeyword || 'location intelligence';
const themes  = blogData.blogThemes   || '';

const FALLBACKS = {

  'hero': [
    `Cinematic hero shot of a professional B2B SaaS map dashboard showing customer account pins`,
    `clustered across a regional US map with teal and navy color-coded territory overlays.`,
    `Clean white sidebar panel with pipeline filter controls visible on the right.`,
    `Dark navy navigation bar at top. Soft depth-of-field background blur on city streets below the map.`,
    `Enterprise marketing photography aesthetic. No human faces. No logos. No text labels on map.`,
    `Color palette: deep navy #1a3c5e, teal #00b4d8, white UI surfaces.`,
    `Ultra-detailed, 4K, professional marketing photography quality.`
  ].join(' '),

  'ui-screenshot': [
    `Clean flat UI screenshot of a SaaS map dashboard at 16:9 aspect ratio.`,
    `Left panel shows an interactive map with color-coded account pins (blue open, green won, muted red lost).`,
    `Right sidebar shows filter controls for pipeline stage, territory owner, and deal amount.`,
    `Top navigation bar with search field and avatar icon. Minimal modern SaaS chrome.`,
    `Map context: ${keyword}. Blog topic: ${title}.`,
    `No text overlays. No watermarks. No brand logos.`,
    `Color palette: navy #1a3c5e headers, teal #00b4d8 active states, white backgrounds.`,
    `Ultra-detailed, 4K, professional SaaS UI design quality.`
  ].join(' '),

  'annotated-map': [
    `Geographic business map with data visualization overlay layers.`,
    `Light gray base map with colored territory polygon overlays and customer location pins inside each region.`,
    `Dense metro area shows clustered pins, sparse rural areas show coverage gaps as white space.`,
    `Color-coded polygon territories: teal, navy, amber, sage green — no overlap, clean boundary lines.`,
    `Subtle pin icons in matching territory colors. No street names or text visible.`,
    `Blog topic: ${keyword}. Key insight: ${themes.split('.')[0] || 'territory coverage optimization'}.`,
    `Professional cartographic quality. No watermarks. No logos.`,
    `Ultra-detailed, 4K, professional data visualization quality.`
  ].join(' '),

  'diagram': [
    `Clean B2B process flow diagram on white background.`,
    `Five connected stages shown as rounded rectangle blocks with a small icon inside each,`,
    `linked by bold right-pointing arrows. Alternating block fill colors: navy, teal, lighter teal, navy, teal.`,
    `Flat design — no drop shadows, no gradients. Horizontal left-to-right flow layout.`,
    `Blog topic: ${keyword}. Process illustrated: ${themes.split('.').slice(0, 2).join(' → ') || 'data input to map output to territory action'}.`,
    `Whitespace between stages. Minimalist enterprise infographic aesthetic.`,
    `No text labels inside blocks. Icon-only indicators. No watermarks. No logos.`,
    `Ultra-detailed, 4K, professional B2B infographic quality.`
  ].join(' '),

  'comparison': [
    `Clean enterprise comparison table graphic on white background.`,
    `Three columns: two representing legacy or generic approaches (labeled with abstract geometric icons),`,
    `one highlighted column on the right representing the modern AI-powered business mapping approach.`,
    `Six evaluation criteria rows with checkmarks, partial marks, and X marks per cell.`,
    `Highlighted column has a teal header background. Other columns have light gray headers.`,
    `Alternating white and very light gray row backgrounds. Navy border accents.`,
    `No real brand names. No logos. No recognizable company UI. Abstract icon headers only.`,
    `Blog context: ${keyword}.`,
    `Color palette: navy #1a3c5e, teal #00b4d8, white, light gray #f5f5f5.`,
    `Ultra-detailed, 4K, professional B2B comparison graphic quality.`
  ].join(' ')
};

const DEFAULT_NEGATIVE = [
  'blurry', 'low quality', 'pixelated', 'text overlay', 'watermark', 'human faces',
  'brand logos', 'recognizable company UI', 'stock photo clichés', 'handshakes',
  'cartoon style', 'comic style', 'anime', 'dark background', 'neon colors',
  'cluttered UI', 'too many elements', 'unrealistic map projections'
].join(', ');

// Apply fallback if AI returned nothing usable
const usedFallback = !imagePrompt || imagePrompt.trim().length < 20;
if (usedFallback) {
  imagePrompt    = FALLBACKS[finalType] || FALLBACKS['hero'];
  negativePrompt = DEFAULT_NEGATIVE;
  console.warn(`Parse Image Prompt: AI returned no usable prompt for type "${finalType}". Using brand fallback.`);
}

if (!negativePrompt || negativePrompt.trim().length < 5) {
  negativePrompt = DEFAULT_NEGATIVE;
}

// ── 5. Determine image filename based on type ──────────────────────────────
const slug = blogData.blogSlug || blogData.slug || 'post';
const typeSuffix = finalType === 'hero' ? 'featured' : finalType;
const defaultFilename = `blog-${slug}-${typeSuffix}.webp`;

// ── 6. Pass everything forward ────────────────────────────────────────────────
return {
  json: {
    // All original blog + image metadata
    ...blogData,

    // Final resolved prompts for Stability AI / Replicate / FAL
    imagePrompt,
    negativePrompt,
    imageType: finalType,

    // Ensure key fields are always present
    imageFilename: blogData.imageFilename || defaultFilename,
    imageSize:     blogData.imageSize     || (finalType === 'hero' ? '1200x630' : '1600x900'),
   // imageAlt:      blogData.suggestedAltText,     

    imageAlt: blogData.imageAlt || blogData.suggestedAltText,

    // Debug metadata
    _promptDebug: {
      rawContentLength:  rawContent.length,
      promptLength:      imagePrompt.length,
      negativeLength:    negativePrompt.length,
      parsedFromAI:      rawContent.length > 0 && !usedFallback,
      usedFallback,
      imageType:         finalType,
      filename:          blogData.imageFilename || defaultFilename,
      rawContent:        rawContent.substring(0, 200) + (rawContent.length > 200 ? '...' : '')
    }
  }
};

