parameters.jsCode:
// ─────────────────────────────────────────────────────────────────────────────
// Process Multiple Images for CMS - Convert Images to Base64
// Handles multiple items, includes image type in filename and alt text
// ─────────────────────────────────────────────────────────────────────────────

const items = $input.all();
const outputItems = [];

// Get blog title from Parse Backlinked Blog node
const blogNode = $('Parse Backlinked Blog');
let rawTitle = 'blog-post';

if (blogNode && blogNode.first()) {
  rawTitle = blogNode.first().json.title || blogNode.first().json.blogTitle || 'blog-post';
}

// Create base slug from title
const baseSlug = rawTitle
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  || 'featured';

// Process each item
for (const item of items) {
  const blogData = item.json || {};

  // Get binary data - preserve the working structure
  let binaryData = null;
  let base64Image = null;

  // Check if binary exists in the expected location
  if (item.binary && item.binary['data']) {
    binaryData = item.binary['data'];
    base64Image = binaryData.data || binaryData;
  } else if (item.binary) {
    // Try to find any binary field
    const keys = Object.keys(item.binary);
    if (keys.length > 0) {
      binaryData = item.binary[keys[0]];
      base64Image = binaryData.data || binaryData;
    }
  }

  // Skip if no binary data
  if (!binaryData) {
    console.warn(`No binary data found for image type: ${blogData.imageType || 'unknown'}`);
    continue;
  }

  // Get image type - use from blogData or default
  const imageType = blogData.imageType || blogData.type || 'featured';

  // Determine filename with image type
  // hero → featured, others keep their type name
  const typeSuffix = imageType === 'hero' ? 'featured' : imageType;

  // Use custom filename if provided, otherwise build from slug + type
  const customFilename = blogData.imageFilename || blogData.filename;
  let fileName;

  if (customFilename) {
    // Use custom filename but ensure .webp extension
    fileName = customFilename.replace(/\.[^.]+$/, '') + '.webp';
  } else {
    fileName = `blog-${baseSlug}-${typeSuffix}.webp`;
  }

  // ── Build alt text with image type context ──────────────────────────────
  // Priority: 1. suggestedAltText, 2. imageAlt, 3. alt, 4. imagePrompt, 5. generate from type
  let altText = blogData.suggestedAltText || 
                blogData.imageAlt || 
                blogData.alt || 
                '';

  // If no alt text was provided, generate one based on image type
  if (!altText) {
    const typeLabels = {
      'hero': 'featured',
      'ui-screenshot': 'UI dashboard screenshot',
      'annotated-map': 'annotated geographic map',
      'diagram': 'process flow diagram',
      'comparison': 'comparison graphic'
    };
    const label = typeLabels[imageType] || imageType;
    altText = `${label} for: ${rawTitle}`;
  }

  // Build output item - preserving the working binary structure
  outputItems.push({
    json: {
      ...blogData,
      imageBase64: base64Image,
      imageFilename: fileName,
      imageType: imageType,
      mimeType: 'image/webp',
      alt: altText,
      suggestedAltText: altText,  // Pass through for CMS
      blogSlug: baseSlug,
      blogTitle: rawTitle,
      // Debug info
      _imageDebug: {
        originalFilename: binaryData.fileName || binaryData.filename || 'unknown',
        fileSize: binaryData.fileSize || 0,
        mimeType: 'image/webp',
        imageType: imageType,
        altText: altText,
        processedAt: new Date().toISOString()
      }
    },
    binary: {
      file: {
        ...binaryData,
        data: base64Image,
        fileName: fileName,
        mimeType: 'image/webp'
      }
    }
  });
}

return outputItems;

// Code node: "Parse Media Response" (Multiple Items)

const items = $input.all();

return items.map(item => {
  const response = item.json;

  // Payload CMS may return either { doc: {...} } or the object directly
  const media = response.doc ?? response;

  const mediaId = media.id;
  const mediaUrl = media.url || '';

  if (!mediaId) {
    throw new Error(`Failed to get media ID for item: ${JSON.stringify(response)}`);
  }

  return {
    json: {
      ...response,
      mediaId,
      mediaUrl,

      // Preserve if it exists
      imageBase64: response.imageBase64 ?? null,
    }
  };
});

