// Collect raw media docs from every possible shape
function collectMediaDocs(nodeName) {
  const collected = [];

  // (a) All items from the node
  const items = readAllItems(nodeName);

  const pushIfMedia = (obj) => {
    if (!obj || typeof obj !== 'object') return;
    // A media doc looks like { doc, mediaId, mediaUrl } or has doc.id
    if (obj.mediaId || obj.doc || obj.id || obj.mediaUrl) {
      collected.push(obj);
    }
  };

  const walk = (node) => {
    if (!node) return;
    if (Array.isArray(node)) { node.forEach(walk); return; }
    if (typeof node !== 'object') return;

    // Current shape: { data: [ ...media... ] }
    if (Array.isArray(node.data)) { node.data.forEach(walk); return; }

    // Some flows: { results: [...] } or { items: [...] } or { media: [...] }
    if (Array.isArray(node.results)) { node.results.forEach(walk); return; }
    if (Array.isArray(node.items))   { node.items.forEach(walk);   return; }
    if (Array.isArray(node.media))   { node.media.forEach(walk);   return; }

    // Otherwise treat as a single media doc
    pushIfMedia(node);
  };

  items.forEach(walk);

  // (b) Fallback: read raw .first().json in case .all() returned nothing useful
  if (collected.length === 0) {
    walk(readNode(nodeName));
  }

  return collected;
}

