  return {
    type:         classifyMedia(item),
    mediaId:      item?.mediaId || doc.id || null,
    url:          item?.mediaUrl || doc.url || '',
    alt:          doc.alt || '',
    filename:     doc.filename || '',
    width:        doc.width || null,
    height:       doc.height || null,
    thumbnailURL: doc.thumbnailURL || doc.sizes?.thumbnail?.url || '',
    order:        idx
  };
}).filter(a => a.mediaId);

