function validateAndSanitizeLexical(editorState) {
  try {
    if (!editorState || !editorState.root) {
      console.error('FATAL: No root node');
      return createMinimalEditorState();
    }
    const sanitized = sanitizeNode(editorState.root);
    const validated = validateEditorState(sanitized);
    if (!validated.valid) {
      console.error('Lexical validation FAILED:', validated.errors.slice(0, 5));
      return createMinimalEditorState();
    }
    return { root: sanitized };
  } catch (err) {
    console.error('validateAndSanitizeLexical FATAL:', err.message);
    return createMinimalEditorState();
  }
}

function sanitizeNode(node) {
