    heading: ['type', 'version', 'direction', 'format', 'indent', 'children', 'tag'],
    quote: ['type', 'version', 'direction', 'format', 'indent', 'children'],
    list: ['type', 'version', 'direction', 'format', 'indent', 'children', 'listType', 'tag', 'start'],
    listitem: ['type', 'version', 'direction', 'format', 'indent', 'children', 'checked', 'value'],
    text: ['type', 'text', 'format', 'detail', 'mode', 'style', 'version'],
    linebreak: ['type', 'version'],
    link: ['type', 'version', 'direction', 'format', 'indent', 'children', 'fields'],
    upload: ['type', 'version', 'relationTo', 'value', 'fields', 'format'],
    horizontalrule: ['type', 'version'],
    table: ['type', 'version', 'direction', 'format', 'indent', 'children', 'colWidths'],
    tablerow: ['type', 'version', 'direction', 'format', 'indent', 'children'],
    tablecell: ['type', 'version', 'headerState', 'colSpan', 'rowSpan', 'backgroundColor', 'children', 'direction', 'format', 'indent']
