    cleaned.url = fieldsObj.url || '';
    cleaned.newTab = fieldsObj.newTab === true;
    cleaned.linkType = fieldsObj.linkType || 'custom';
  } else if (nodeType === 'upload') {
    cleaned.alt = fieldsObj.alt || '';
    cleaned.caption = fieldsObj.caption || '';
  }
  return cleaned;
