function validateEditorState(root) {
  const errors = [];
  if (root.type !== 'root') errors.push('Root type must be root');
  if (!Array.isArray(root.children) || root.children.length === 0) errors.push('Root children empty');
  validateNodeChildren(root, errors, 'root');
  return { valid: errors.length === 0, errors };
}

function validateNodeChildren(node, errors, parentPath) {
  if (!node.children || !Array.isArray(node.children)) return;

  node.children.forEach((child, idx) => {
    const path = `${parentPath}[${idx}]`;
    if (!child.type) {
      errors.push(`${path}: no type`);
      return;
    }

    if (child.type === 'text') {
      if (typeof child.text !== 'string') errors.push(`${path}: text not string`);
      if (typeof child.format !== 'number') errors.push(`${path}: format not number`);
    } else if (child.type === 'paragraph') {
      if (!Array.isArray(child.children)) errors.push(`${path}: no children`);
    } else if (child.type === 'table') {
      if (!Array.isArray(child.children)) errors.push(`${path}: no rows`);
      if (!Array.isArray(child.colWidths)) errors.push(`${path}: no colWidths`);
      validateTableStructure(child, errors, path);
    } else if (child.type === 'tablerow') {
      if (!Array.isArray(child.children)) errors.push(`${path}: no cells`);
    } else if (child.type === 'tablecell') {
      if (!Array.isArray(child.children)) errors.push(`${path}: no cell content`);
      if (typeof child.colSpan !== 'number') errors.push(`${path}: colSpan not number`);
      if (typeof child.rowSpan !== 'number') errors.push(`${path}: rowSpan not number`);
    }

    validateNodeChildren(child, errors, path);
  });
}

function validateTableStructure(table, errors, path) {
  if (!table.children || table.children.length === 0) {
    errors.push(`${path}: table empty`);
    return;
  }

  table.children.forEach((row, rIdx) => {
    const rPath = `${path}.row[${rIdx}]`;
    if (row.type !== 'tablerow') errors.push(`${rPath}: not tablerow`);
    if (!row.children || row.children.length === 0) errors.push(`${rPath}: no cells`);

    row.children.forEach((cell, cIdx) => {
      const cPath = `${rPath}.cell[${cIdx}]`;
      if (cell.type !== 'tablecell') errors.push(`${cPath}: not tablecell`);
      if (!cell.children || cell.children.length === 0) errors.push(`${cPath}: no content`);
    });
  });
}

