    }

    const rows = [];
    const rowRe = /<tr\b[^>]*>/gi;
    let match;
    let rowCount = 0;

    while ((match = rowRe.exec(inner))) {
      try {
        const openEnd = match.index + match[0].length;
        const closeIdx = findMatchingClose(inner, 'tr', openEnd);
        const rowInner = inner.slice(openEnd, closeIdx);
        rowRe.lastIndex = closeIdx;

        const cells = [];
        const cellRe = /<(td|th)(?:\s[^>]*)?>([^<]*)<\/\1>/gi;
        let cellMatch;

        while ((cellMatch = cellRe.exec(rowInner))) {
          try {
            const cTag = cellMatch[1].toLowerCase();
            const cellText = cellMatch[2] || '';
            const isHeader = cTag === 'th';
            const cellChildren = parseInline(cellText);

            cells.push({
              type: 'tablecell',
              version: 2,
              headerState: isHeader ? 1 : 0,
              colSpan: 1,
              rowSpan: 1,
              backgroundColor: null,
              children: [{
                type: 'paragraph',
                children: cellChildren.length ? cellChildren : [makeText('', 0)],
                direction: 'ltr',
                format: '',
                indent: 0,
                version: 1
              }],
              direction: 'ltr',
              format: '',
              indent: 0
            });
          } catch (cellErr) {
            console.warn(`cell parse error in row ${rowCount}`);
            cells.push({
              type: 'tablecell',
              version: 2,
              headerState: 0,
              colSpan: 1,
              rowSpan: 1,
              backgroundColor: null,
              children: [{
                type: 'paragraph',
                children: [makeText('[Cell Error]', 0)],
                direction: 'ltr',
                format: '',
                indent: 0,
                version: 1
              }],
              direction: 'ltr',
              format: '',
              indent: 0
            });
          }
        }

        if (cells.length > 0) {
          rows.push({
            type: 'tablerow',
            version: 2,
            children: cells,
            direction: 'ltr',
            format: '',
            indent: 0
          });
          rowCount++;
        }
      } catch (rowErr) {
        console.warn(`row parse error at ${rowCount}`);
        continue;
      }
    }

    if (rows.length === 0) {
      return createEmptyTable();
    }

    return {
      type: 'table',
      version: 2,
      children: rows,
      direction: 'ltr',
      format: '',
      indent: 0,
      colWidths: []
    };

  } catch (err) {
    console.error('parseTable FATAL:', err.message);
    return createEmptyTable();
  }
}

function createEmptyTable() {
  return {
    type: 'table',
    version: 2,
    children: [{
      type: 'tablerow',
      version: 2,
      children: [{
        type: 'tablecell',
        version: 2,
        headerState: 1,
        colSpan: 1,
        rowSpan: 1,
        backgroundColor: null,
        children: [{
          type: 'paragraph',
          children: [makeText('[Table Parse Failed]', 0)],
          direction: 'ltr',
          format: '',
          indent: 0,
          version: 1
        }],
        direction: 'ltr',
        format: '',
        indent: 0
      }],
      direction: 'ltr',
      format: '',
      indent: 0
    }],
    direction: 'ltr',
    format: '',
    indent: 0,
    colWidths: []
  };
}

function buildBlockNode(block) {
  if (block.tag === 'hr') return { type: 'horizontalrule', version: 1 };

  if (/^h[1-6]$/.test(block.tag)) {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'heading', tag: block.tag, children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'p') {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'paragraph', children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'blockquote') {
    const children = parseInline(block.inner);
    if (!children.length) return null;
    return { type: 'quote', children, direction: 'ltr', format: '', indent: 0, version: 1 };
  }

  if (block.tag === 'ul' || block.tag === 'ol') return buildListNode(block.tag, block.inner);

  if (block.tag === 'table') {
    try {
      return parseTable(block.inner);
    } catch (err) {
      console.error('table parse failed');
      return createEmptyTable();
    }
  }

  const children = parseInline(block.inner);
  if (!children.length) return null;
  return { type: 'paragraph', children, direction: 'ltr', format: '', indent: 0, version: 1 };
}

function buildUploadNode(asset) {
  if (!asset || !asset.mediaId) return null;
  return {
    type: 'upload',
    relationTo: MEDIA_RELATION_TO,
    value: asset.mediaId,
    fields: { alt: asset.alt || '', caption: asset.alt || '' },
    format: '',
    version: 3
  };
}

function htmlToLexical(html, inBodyAssets) {
  const cleaned = (html || '').replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
  const blocks = splitBlocks(cleaned);
  let children = blocks.map(buildBlockNode).filter(Boolean);

  const images = (inBodyAssets || []).map(buildUploadNode).filter(Boolean);

  if (images.length && children.length) {
    const headingIdxs = [];
    children.forEach((node, i) => {
      if (node.type === 'heading' && /^h[23]$/.test(node.tag)) headingIdxs.push(i);
    });

    const withImages = [];
    let imgPointer = 0;

    if (headingIdxs.length >= images.length) {
      const step = Math.max(1, Math.floor(headingIdxs.length / images.length));
      const anchorSet = new Set();
      for (let k = 0; k < images.length; k++) {
        const anchor = headingIdxs[Math.min(headingIdxs.length - 1, (k + 1) * step - 1)];
        anchorSet.add(anchor);
      }
      const anchors = [...anchorSet];
      children.forEach((node, i) => {
        withImages.push(node);
        if (anchors.includes(i) && imgPointer < images.length) {
          withImages.push(images[imgPointer++]);
        }
      });
      while (imgPointer < images.length) withImages.push(images[imgPointer++]);
    } else {
      const gap = Math.max(1, Math.floor(children.length / (images.length + 1)));
      children.forEach((node, i) => {
        withImages.push(node);
        if (i > 0 && i % gap === 0 && imgPointer < images.length) {
          withImages.push(images[imgPointer++]);
        }
      });
      while (imgPointer < images.length) withImages.push(images[imgPointer++]);
    }

    children = withImages;
  }

  return {
    root: {
      type: 'root',
      direction: 'ltr',
      format: '',
      indent: 0,
      version: 1,
      children: children.length
        ? children
        : [{ type: 'paragraph', children: [makeText('', 0)], direction: 'ltr', format: '', indent: 0, version: 1 }]
    }
  };
}

function pick(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}

function buildAuthorField(authorId) {
  const id = (authorId || '').trim();
  if (!id) return null;
  if (AUTHOR_FIELD_TYPE === 'polymorphic') return { relationTo: AUTHOR_RELATION_TO, value: id };
  if (AUTHOR_FIELD_TYPE === 'hasMany') return [id];
  return id;
}

function buildSearchKeywords(rawList) {
  const clean = (Array.isArray(rawList) ? rawList : [])
    .map(k => typeof k === 'string' ? k : (k?.keyword || k?.text || ''))
    .map(k => k.trim())
    .filter(Boolean);
  return SEARCH_KEYWORDS_FIELD_TYPE === 'array' ? clean.map(keyword => ({ keyword })) : clean;
}

// ===================== MAIN =====================

const input = $input.first().json;
const blog = input.parseBlog || {};
const backlinked = input.parseBacklinkedBlog || {};

const title = pick(input.title, blog.title, backlinked.title) || '';
const slug = pick(input.slug, blog.slug, backlinked.slug) || '';
const excerpt = pick(input.excerpt, blog.excerpt, backlinked.excerpt) || '';
const quickAnswer = pick(input.quickAnswer, blog.quickAnswer, backlinked.quickAnswer) || '';
const featuredVideo = pick(input.featuredVideo, blog.featuredVideo, backlinked.featuredVideo) || '';

if (!slug) {
  throw new Error('Prepare Payload1: missing slug');
}

const sourceHtml = pick(
  input.blogContent, backlinked.blogContent, blog.blogContent,
  input.content, backlinked.content, blog.content
) || '';

const detectedLinks = (sourceHtml.match(/<a\s+href=/gi) || []).length;

const mediaIds = input.mediaIds || {};
const mediaAssets = Array.isArray(input.mediaAssets) ? input.mediaAssets : [];
const featuredImageId = mediaIds.featured || input.mediaId || (mediaAssets[0] ? mediaAssets[0].mediaId : null);
const inBodyAssets = mediaAssets.filter(a => a.mediaId && a.mediaId !== featuredImageId);

const videoAssets = Array.isArray(input.videoAssets) ? input.videoAssets : [];
const videoMediaIds = Array.isArray(input.videoMediaIds) ? input.videoMediaIds : [];
const featuredVideoId = input.videoMediaId || (videoAssets[0] ? videoAssets[0].mediaId : null) || (videoMediaIds[0] || null);
const inBodyVideoAssets = videoAssets.filter(a => a.mediaId);

const authorId = pick(input.authorId, input.author, blog.authorId, DEFAULT_AUTHOR_ID);
const authorField = buildAuthorField(authorId);
const canonicalUrl = `${SITE_BASE_URL.replace(/\/$/, '')}/blog/${slug}`;

const focusKeyword = pick(
  input.focusKeyword, blog.blog?.['Focus Keyword'], backlinked.blog?.['Focus Keyword']
) || '';

const rawSearchKeywords = pick(
  input.searchKeywords, blog.searchKeywords, backlinked.searchKeywords,
  focusKeyword ? [focusKeyword] : undefined
) || [];
const searchKeywords = buildSearchKeywords(rawSearchKeywords);

const rawKeyTakeaways = input.keyTakeaways || blog.keyTakeaways || backlinked.keyTakeaways || [];
const keyTakeaways = (Array.isArray(rawKeyTakeaways) ? rawKeyTakeaways : []).map(item => ({
  text: (typeof item === 'string') ? item : (item?.text || '')
}));

const rawFaq = input.faq || blog.faq || backlinked.faq || [];
const faq = (Array.isArray(rawFaq) ? rawFaq : []).map(item => ({
  question: item.question || '',
  answer: item.answer || ''
}));

const h1Text = pick(title, blog.blog?.['Headline']) || '';
const htmlWithH1 = h1Text
  ? `<h1>${h1Text}</h1>\n${sourceHtml}`
  : `<h1>${title}</h1>\n${sourceHtml}`;

const category = blog.blog?.['Category'] || 'Tips';

let metaTitle = pick(title, blog.blog?.['Meta Title']) || '';
if (metaTitle.length > 60) {
  metaTitle = metaTitle.slice(0, 57) + '...';
}

// ✅ Convert HTML → Lexical, THEN validate and sanitize
let lexicalContent = htmlToLexical(htmlWithH1, [...inBodyAssets, ...inBodyVideoAssets]);

// ✅ CRITICAL: Validate and sanitize before sending to Payload
console.log('Validating Lexical structure...');
lexicalContent = validateAndSanitizeLexical(lexicalContent);
console.log('Lexical structure validated successfully');

const payload = {
  title, slug, excerpt, featuredImage: featuredImageId || null,
  featuredVideoMedia: featuredVideoId || null,
  content: lexicalContent,
  quickAnswer,
  ...(authorField !== null ? { author: authorField } : {}),
  keyTakeaways,
  seo: {
    metaTitle, metaDescription: excerpt, noIndex: false, noFollow: false,
    focusKeyword, schemaType: 'BlogPosting', searchKeywords, canonicalUrl
  },
  faq, canonicalUrl, _status: 'draft'
};

return {
  json: {
    body: payload, payload,
    mediaId: featuredImageId || null, mediaIds,
    videoMediaId: featuredVideoId || null, videoMediaIds,
    _payloadDebug: {
      title, slug, canonicalUrl, sourceHtmlLength: sourceHtml.length,
      internalLinkCount: detectedLinks, linksInLexical: JSON.stringify(lexicalContent).includes('"type":"link"'),
      keyTakeawaysCount: keyTakeaways.length, faqCount: faq.length, searchKeywords,
      featuredImage: featuredImageId || null, totalMediaAssets: mediaAssets.length,
      inBodyImageCount: inBodyAssets.length, inBodyImageTypes: inBodyAssets.map(a => a.type),
      uploadsInLexical: (JSON.stringify(lexicalContent).match(/"type":"upload"/g) || []).length,
      featuredVideoMedia: featuredVideoId || null, totalVideoAssets: videoAssets.length,
      inBodyVideoCount: inBodyVideoAssets.length,
      videoMimeTypes: videoAssets.map(a => a.mimeType).filter(Boolean),
      lexicalValidationPassed: true
    }
  }
};

} catch (err) {
  return {
    json: {
      error: true, errorMessage: err.message, errorStack: err.stack,
      rawInput: $input.first().json
    }
  };
}

// Code Node: "Generate Video Prompt"
