const item = $input.first();
const input = item.json;

// Extract video data from Sora response format
const videoData = input?.data?.[0] || {};

// Get video URL — prefer Sora direct URL, fallback to videoUrl field
const videoUrl = videoData?.url || input?.videoUrl || '';

if (!videoUrl) {
  throw new Error('No video URL found. Check Generate a video node output.');
}

// Get metadata
const metadata = input?.metadata || {};
const videoTitle    = metadata?.videoTitle    || input?.videoTitle    || 'DotlyMaps Tutorial';
const videoFilename = metadata?.videoFilename || input?.videoFilename || 'blog-tutorial.mp4';
const videoAlt      = metadata?.videoAlt      || input?.videoAlt      || `Video tutorial: ${videoTitle}`;
const videoSource   = input?.videoSource || (videoData?.url ? 'sora-generated' : 'youtube-fallback');

// Ensure .mp4 extension
const cleanFilename = videoFilename.endsWith('.mp4') ? videoFilename : `${videoFilename}.mp4`;

return [{
  json: {
    ...input,

    // Resolved video fields
    videoUrl,
    videoTitle,
    videoFilename: cleanFilename,
    videoAlt,
    videoSource,
    alt: videoAlt,
    mimeType: 'video/mp4',

    // Extra metadata from Sora
    videoDuration:  videoData?.duration   || metadata?.duration_seconds || 0,
    videoWidth:     videoData?.width      || 1920,
    videoHeight:    videoData?.height     || 1080,
    videoFps:       videoData?.fps        || 30,
    videoFormat:    videoData?.format     || 'mp4',
    thumbnailUrl:   videoData?.thumbnail_url || '',
    revisedPrompt:  videoData?.revised_prompt || '',

    _videoDebug: {
      sourceUrl:   videoUrl,
      filename:    cleanFilename,
      altText:     videoAlt,
      source:      videoSource,
      preparedAt:  new Date().toISOString()
    }
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Prepare Video Binary
// Merges downloaded binary with video metadata, renames binary key to 'file'
// so the VIDEO UPLOADING node can reference inputDataFieldName = 'file'
// ─────────────────────────────────────────────────────────────────────────────

const item  = $input.first();
const binary = item.binary;

// Pull metadata from the upstream Process Video for CMS node
const videoMeta = $('Process Video for CMS').first().json;

if (!binary || !Object.keys(binary).length) {
  throw new Error('No binary data after video download. Check Download Video from URL node.');
}

// n8n stores downloaded file under 'data' by default — grab whichever key exists
const binaryKey  = Object.keys(binary)[0];
const binaryData = binary[binaryKey];

const videoFilename = videoMeta.videoFilename || 'blog-tutorial.mp4';
const videoAlt      = videoMeta.videoAlt      || 'Blog tutorial video';

return [{
  json: {
    ...videoMeta,
    alt:           videoAlt,
    videoFilename: videoFilename,
    mimeType:      'video/mp4',

    _binaryDebug: {
      originalKey:  binaryKey,
      originalMime: binaryData.mimeType || 'unknown',
      fileSize:     binaryData.fileSize  || 0,
      renamedTo:    'file',
      preparedAt:   new Date().toISOString()
    }
  },
  binary: {
    // Rename to 'file' — matches inputDataFieldName in VIDEO UPLOADING node
    file: {
      ...binaryData,
      fileName: videoFilename,
      mimeType: 'video/mp4'
    }
  }
}];

// Parse Video Media Response
// Same pattern as Parse Media Response for images

const items = $input.all();

return items.map(item => {
  const response = item.json;

  // Payload CMS returns either { doc: {...} } or the object directly
  const media = response.doc ?? response;

