outlineItems.forEach((heading, index) => {
  // Special handling for FAQ: keep it as "FAQ" in the heading.
  const h2Tag = heading.toLowerCase().includes('faq') ? 'FAQ' : heading;

  // Instruction line for each H2
  dynamicH2Instructions += `${index + 1}. H2: "${heading}"\n   - Section ${index + 1}: Cover the key points related to this topic.\n`;

  // Example line for each H2
  dynamicH2Example += `<h2>${heading}</h2>\n<p>Content for "${heading}"...</p>\n`;
