// 1. SHARED HELPERS ---------------------------------------------------------

function stripTags(html) {
  return (html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function extractQuickAnswer(html) {
  if (!html) return '';
  const quickAnswerMatch = html.match(/Quick answer:?\s*([^.<>]+[.!?]?)/i);
  if (quickAnswerMatch) {
    let answer = stripTags(quickAnswerMatch[1]);
    if (answer.length > 320) answer = answer.slice(0, 317).trim() + '...';
    return answer;
  }
  const m = (html || '').match(/<p[^>]*>([\s\S]*?)<\/p>/i);
  if (!m) return '';
  const text = stripTags(m[1]);
  const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];
  let answer = sentences.slice(0, 2).join(' ').trim();
  if (answer.length > 320) answer = answer.slice(0, 317).trim() + '...';
  return answer;
}

function extractKeyTakeaways(html) {
  if (!html) return [];
  const headingRe = /<h[2-4][^>]*>\s*[^<]*key\s*takeaways?[^<]*<\/h[2-4]>([\s\S]*?)(?=<h[1-4]|$)/i;
  const m = (html || '').match(headingRe);
  if (!m) return [];
  const ulMatch = m[1].match(/<ul[^>]*>([\s\S]*?)<\/ul>/i);
  if (!ulMatch) return [];
  const liRe = /<li[^>]*>([\s\S]*?)<\/li>/gi;
  const items = [];
  let lm;
  while ((lm = liRe.exec(ulMatch[1]))) {
    const text = stripTags(lm[1]);
    if (text) items.push({ text });
  }
  return items;
}

function extractFaq(html) {
  if (!html) return [];
  const faqs = [];
  const headingRe = /<h[2-4][^>]*>([^<]*\?)\s*<\/h[2-4]>\s*<p[^>]*>([\s\S]*?)<\/p>/gi;
  let m;
  while ((m = headingRe.exec(html || ''))) {
    const question = stripTags(m[1]);
    let answer = stripTags(m[2]);
    if (answer.length > 400) answer = answer.slice(0, 397).trim() + '...';
    if (question && answer) faqs.push({ question, answer });
  }
  return faqs;
}

// Normalize keyTakeaways to always be [{text: "..."}] objects
function normalizeKeyTakeaways(raw) {
  if (!Array.isArray(raw)) return [];
  return raw
    .map(item => {
      if (typeof item === 'string') return { text: item.trim() };
      if (item && typeof item === 'object') return { text: (item.text || '').trim() };
      return null;
    })
    .filter(item => item && item.text);
}

// Normalize faq to always be [{question, answer}] objects
function normalizeFaq(raw) {
  if (!Array.isArray(raw)) return [];
  return raw
    .map(item => {
      if (!item || typeof item !== 'object') return null;
      const question = (item.question || '').trim();
      const answer = (item.answer || '').trim();
      if (!question || !answer) return null;
      return { question, answer };
    })
    .filter(Boolean);
}

// 2. H1 VALIDATION HELPERS --------------------------------------------------

function extractH1(html) {
  if (!html) return { text: null, present: false, tag: null, warning: null };
  const h1Match = html.match(/<h1[^>]*>\s*([^<]+?)\s*<\/h1>/i);
  if (h1Match) {
    return {
      text: stripTags(h1Match[1]),
      present: true,
      tag: '<h1>',
      warning: null
    };
  }
  const h1CaseMatch = html.match(/<H1[^>]*>\s*([^<]+?)\s*<\/H1>/i);
  if (h1CaseMatch) {
    return {
      text: stripTags(h1CaseMatch[1]),
      present: true,
      tag: '<H1>',
      warning: 'H1 tag should be lowercase'
    };
  }
  return { text: null, present: false, tag: null, warning: null };
}

function validateHeadingHierarchy(html) {
  const headings = [];
  const headingRe = /<(h[1-6])[^>]*>\s*([^<]+?)\s*<\/h[1-6]>/gi;
  let m;
  while ((m = headingRe.exec(html))) {
    const level = parseInt(m[1].replace('h', ''));
    headings.push({
      level: level,
      text: stripTags(m[2]),
      tag: m[1]
    });
  }
  const issues = [];
  if (headings.length === 0) {
    issues.push('No headings found in content');
    return { valid: false, headings, issues };
  }
  if (headings[0].level !== 1) {
    issues.push(`First heading is H${headings[0].level}, should be H1: "${headings[0].text}"`);
  }
  let expectedLevel = 1;
  for (const h of headings) {
    if (h.level > expectedLevel + 1) {
      issues.push(`Heading level skipped: H${expectedLevel} → H${h.level}: "${h.text}"`);
    }
    expectedLevel = h.level;
  }
  return { valid: issues.length === 0, headings, issues };
}

// 3. DYNAMIC H2 STRUCTURE VALIDATION (based on Outline) -----------------------

// New normalization function for exact matching
function normalizeHeading(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function validateRequiredH2Structure(html, requiredH2s) {
  if (!requiredH2s || requiredH2s.length === 0) {
    return {
      valid: true,
      foundH2s: [],
      missing: [],
      missingCount: 0,
      orderValid: true,
      foundCount: 0,
      requiredCount: 0
    };
  }

  const h2Re = /<h2[^>]*>\s*([\s\S]*?)\s*<\/h2>/gi;
  const foundH2s = [];
  let m;
  while ((m = h2Re.exec(html || ''))) {
    foundH2s.push(stripTags(m[1]));
  }

  const normalizedFound = foundH2s.map(normalizeHeading);
  const normalizedRequired = requiredH2s.map(normalizeHeading);

  const missing = normalizedRequired.filter(
    req => !normalizedFound.includes(req)
  );

  const orderValid =
    missing.length === 0 &&
    normalizedRequired.every(
      (req, index) => normalizedFound[index] === req
    );

  return {
    valid: missing.length === 0 && orderValid && foundH2s.length === requiredH2s.length,
    foundH2s,
    requiredH2s,
    missingCount: missing.length,
    missing,
    orderValid,
    foundCount: foundH2s.length,
    requiredCount: requiredH2s.length
  };
}

// 4. CONTENT QUALITY CHECKS ---------------------------------------------------

function validateContentQuality(html, faq, quickAnswer, focusKeyword) {
  const issues = [];

  const wordCount = stripTags(html).split(/\s+/).filter(Boolean).length;
  if (wordCount < 1500) {
    issues.push(`Word count is ${wordCount}, below the 1,500 minimum (free model limit)`);
  } else if (wordCount < 3000) {
    issues.push(`Word count is ${wordCount}, below the 3,000 target (free model limitation)`);
  }

  if (html.includes('—')) {
    issues.push('Em dash (—) found in content — voice guidelines forbid this');
  }

  const percentMatches = html.match(/\d{1,3}%/g);
  if (percentMatches && percentMatches.length > 0) {
    issues.push(`Possible invented statistic(s) found: ${percentMatches.join(', ')} — verify these are sourced or reword to directional language`);
  }

  if (faq.length === 0) {
    issues.push('FAQ array is empty');
  }
  if (faq.length < 4) {
    issues.push(`FAQ has only ${faq.length} question(s), needs at least 4`);
  }

  if (!quickAnswer || quickAnswer.length < 20) {
    issues.push('quickAnswer is missing or too short');
  } else if (/^</.test(quickAnswer.trim())) {
    issues.push('quickAnswer appears to contain an HTML tag — should be a plain paragraph');
  } else if (focusKeyword && !quickAnswer.toLowerCase().includes(focusKeyword.toLowerCase())) {
    issues.push(`quickAnswer does not include focus keyword "${focusKeyword}"`);
  }

  const criticalIssues = issues.filter(i =>
    i.includes('empty') ||
    i.includes('missing') ||
    i.includes('does not include focus')
  );

  return {
    valid: criticalIssues.length === 0,
    issues,
    wordCount,
    hasWarnings: issues.length > 0
  };
}

