  console.log('⚠️ H1 warning:', h1Info.warning);
  console.log('   H1 text:', h1Info.text);
} else {
  console.log('✅ H1 found and stripped from content:', h1Info.text);
}

if (!hierarchyValidation.valid) {
  console.log('⚠️ Heading hierarchy issues after H1 strip:', hierarchyValidation.issues.join('; '));
  const falsePositive = hierarchyValidation.issues.some(i =>
    i.includes('HNaN') || i.includes('should be H1')
  );
  if (falsePositive) {
    console.log('⚠️ False positive detected in hierarchy check — ignoring');
    hierarchyValidation.valid = true;
    hierarchyValidation.issues = hierarchyValidation.issues.filter(i =>
      !i.includes('HNaN') && !i.includes('should be H1')
    );
  }
} else {
  console.log('✅ Heading hierarchy valid (H2 is now first heading after strip)');
}

if (!h2StructureValidation.valid) {
  console.log(`❌ Missing ${h2StructureValidation.missingCount} required H2 section(s):`, h2StructureValidation.missing.join(', '));
  console.log('   H2s found:', h2StructureValidation.foundH2s.join(' | '));
} else {
  console.log('✅ All required H2 sections present in correct order');
}

const contentQuality = validateContentQuality(contentHtml, faq, quickAnswer, focusKeyword);
if (!contentQuality.valid) {
  console.log('❌ Critical content quality issues:', contentQuality.issues.join(' | '));
} else if (contentQuality.hasWarnings) {
  console.log('⚠️ Content quality warnings:', contentQuality.issues.join(' | '));
} else {
  console.log(`✅ Content quality checks passed (${contentQuality.wordCount} words)`);
}

// 11. BUILD THE RESULT ---------------------------------------------------------

return [{
