// ============================================================
// INPUT FOR PROMPT
// Dynamic DotlyMaps Internal Linking Database
// ============================================================

const items = $input.all();

const DOMAIN = 'https://dotlymaps.com';

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function buildFullUrl(path) {
  if (path === null || path === undefined) {
    return null;
  }

  const value = String(path).trim();

  if (!value) {
    return null;
  }

  if (
    value.startsWith('https://') ||
    value.startsWith('http://')
  ) {
    return value;
  }

  if (value === '/') {
    return null;
  }

  if (value.startsWith('/')) {
    return DOMAIN + value;
  }

  return `${DOMAIN}/${value}`;
}

function cleanString(value) {
  return String(value ?? '').trim();
}

function normalizeTitle(value) {
  return cleanString(value)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(value) {
  return normalizeTitle(value)
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    '\\$&'
  );
}

function extractExistingLinks(html) {
  if (!html) return [];

  return [
    ...html.matchAll(
      /<a\b[^>]*href=["']([^"']+)["'][^>]*>/gi
    )
  ].map(match => match[1]);
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

// ------------------------------------------------------------
// BUILD ALL POSTS FROM GET ALL LINKS
//
// IMPORTANT:
// Dynamically captures every "Required Link N" column.
// No fixed limit of 3.
// ------------------------------------------------------------

const allPosts = items
  .map(item => {
    const row = item.json || {};

    const slug = cleanString(row['Slug']);
    const title = cleanString(row['Post Title']);

    if (!slug) {
      return null;
    }

    // -----------------------------------------------
    // Collect ALL Required Link N fields dynamically
    // -----------------------------------------------

    const requiredLinksByColumn = {};

    for (const [key, value] of Object.entries(row)) {
      if (
        /^Required Link\s+\d+$/i.test(key) &&
        value !== null &&
        value !== undefined &&
        cleanString(value) !== ''
      ) {
        const fullUrl = buildFullUrl(value);

        if (fullUrl) {
          requiredLinksByColumn[key] = fullUrl;
        }
      }
    }

    // Sort Required Link 1, 2, 3, 4...
    const sortedRequiredLinkEntries =
      Object.entries(requiredLinksByColumn)
        .sort((a, b) => {
          const aNum =
            parseInt(a[0].match(/\d+/)?.[0] || '0', 10);

          const bNum =
            parseInt(b[0].match(/\d+/)?.[0] || '0', 10);

          return aNum - bNum;
        });

    // -----------------------------------------------
    // Convert into clean array
    // -----------------------------------------------

    const requiredLinks = [];

    const seenRequiredUrls = new Set();

    for (const [column, url] of sortedRequiredLinkEntries) {

      if (seenRequiredUrls.has(url)) {
        continue;
      }

      seenRequiredUrls.add(url);

      const numberMatch = column.match(/\d+/);

      requiredLinks.push({
        number: numberMatch
          ? parseInt(numberMatch[0], 10)
          : null,

        column,

        url
      });
    }

    return {
      name: title || slug,
      slug,
      postNumber: row['Post #'] || null,

      // Primary CTA remains separate
      primaryCTA:
        buildFullUrl(row['Primary CTA']),

      // New dynamic collection
      requiredLinks,

      // Keep original fields for backward compatibility
      requiredLink1:
        buildFullUrl(row['Required Link 1']),

      requiredLink2:
        buildFullUrl(row['Required Link 2']),

      requiredLink3:
        buildFullUrl(row['Required Link 3']),

      // Keep any future direct fields if they exist
      requiredLink4:
        buildFullUrl(row['Required Link 4']),

      requiredLink5:
        buildFullUrl(row['Required Link 5']),

      requiredLink6:
        buildFullUrl(row['Required Link 6']),

      url:
        `${DOMAIN}/blog/${slug}`
    };
  })
  .filter(Boolean);

// ------------------------------------------------------------
// READ CURRENT BLOG
// ------------------------------------------------------------

const blogData =
  $('Parse Humanized Blog').first().json || {};

const blogContent =
  blogData.content ||
  blogData.blogContent ||
  '';

const currentSlug =
  cleanString(blogData.slug);

const currentTitle =
  cleanString(
    blogData.title ||
    blogData.blog?.['Headline'] ||
    ''
  );

// ------------------------------------------------------------
// MATCH CURRENT POST
//
// Priority:
// 1. Exact slug
// 2. Exact title
// 3. Exact normalized slug generated from title
// 4. Partial title
//
// This keeps your existing fallback behavior but improves it.
// ------------------------------------------------------------

let currentPost = null;
let matchMethod = 'none';

// ------------------------------------------------------------
// 1. Exact slug
// ------------------------------------------------------------

if (currentSlug) {

  currentPost = allPosts.find(
    post => post.slug === currentSlug
  );

  if (currentPost) {
    matchMethod = 'exact_slug';
  }
}

// ------------------------------------------------------------
// 2. Exact title
// ------------------------------------------------------------

if (!currentPost && currentTitle) {

  const normalizedCurrentTitle =
    normalizeTitle(currentTitle);

  currentPost = allPosts.find(
    post =>
      normalizeTitle(post.name) ===
      normalizedCurrentTitle
  );

  if (currentPost) {
    matchMethod = 'exact_title';
  }
}

// ------------------------------------------------------------
// 3. Generated slug comparison
// ------------------------------------------------------------

if (!currentPost && currentTitle) {

  const generatedCurrentSlug =
    slugify(currentTitle);

  currentPost = allPosts.find(
    post =>
      post.slug === generatedCurrentSlug
  );

  if (currentPost) {
    matchMethod = 'generated_title_slug';
  }
}

// ------------------------------------------------------------
// 4. Partial title fallback
// ------------------------------------------------------------

if (!currentPost && currentTitle) {

  const normalizedCurrentTitle =
    normalizeTitle(currentTitle);

  const candidates = allPosts.filter(post => {

    const rowTitle =
      normalizeTitle(post.name);

    return (
      rowTitle.includes(normalizedCurrentTitle) ||
      normalizedCurrentTitle.includes(rowTitle)
    );
  });

  // If multiple candidates exist, prefer the longest
  // matching title to reduce accidental matches.
  if (candidates.length > 0) {

    candidates.sort(
      (a, b) =>
        normalizeTitle(b.name).length -
        normalizeTitle(a.name).length
    );

    currentPost = candidates[0];
    matchMethod = 'partial_title';
  }
}

// ------------------------------------------------------------
// Build dynamic required links for current post
//
// IMPORTANT:
// The primary CTA is kept separate from requiredLinks.
// ------------------------------------------------------------

let requiredLinks = [];

let primaryCTA = null;

if (currentPost) {

  primaryCTA =
    currentPost.primaryCTA || null;

  // Copy dynamically collected required links
  requiredLinks =
    Array.isArray(currentPost.requiredLinks)
      ? currentPost.requiredLinks.map(link => ({
          number: link.number,
          column: link.column,
          url: link.url
        }))
      : [];

  // Remove duplicate URLs while preserving order
  const seen = new Set();

  requiredLinks =
    requiredLinks.filter(link => {

      if (!link.url) {
        return false;
      }

      if (seen.has(link.url)) {
        return false;
      }

      seen.add(link.url);
      return true;
    });
}

// ------------------------------------------------------------
// Add suggested anchors
//
// Default anchor comes from URL slug.
// The AI is told these are suggestions only.
// ------------------------------------------------------------

requiredLinks =
  requiredLinks.map(link => {

    const lastPart =
      link.url
        .split('/')
        .filter(Boolean)
        .pop() || '';

    const suggestedAnchor =
      lastPart
        .replace(/-/g, ' ')
        .trim();

    return {
      ...link,
      suggestedAnchor
    };
  });

// ------------------------------------------------------------
// PRIMARY CTA OBJECT
// ------------------------------------------------------------

const primaryCTAInfo = primaryCTA
  ? {
      url: primaryCTA,
      suggestedAnchor:
        primaryCTA
          .split('/')
          .filter(Boolean)
          .pop()
          ?.replace(/-/g, ' ') || 'business mapping',
      type: 'primary_cta'
    }
  : null;

// ------------------------------------------------------------
// OTHER POSTS
// ------------------------------------------------------------

const otherPosts = allPosts.filter(
  post =>
    !currentPost ||
    post.slug !== currentPost.slug
);

// ------------------------------------------------------------
// EXISTING LINKS IN CURRENT BLOG
// ------------------------------------------------------------

const existingLinks =
  extractExistingLinks(blogContent);

const existingUniqueLinks =
  unique(existingLinks);

// ------------------------------------------------------------
// URLs already present in source
// ------------------------------------------------------------

const existingRequiredUrls =
  requiredLinks
    .filter(link =>
      existingUniqueLinks.includes(link.url)
    )
    .map(link => link.url);

// ------------------------------------------------------------
// REQUIRED LINKS THAT ARE STILL MISSING
// ------------------------------------------------------------

const missingRequiredUrls =
  requiredLinks
    .filter(link =>
      !existingUniqueLinks.includes(link.url)
    )
    .map(link => link.url);

// ------------------------------------------------------------
// RELATED POST DATABASE
//
// Only expose useful information.
// The AI does not need every raw sheet column.
// ------------------------------------------------------------

const relatedPosts =
  otherPosts.map(post => ({
    name: post.name,
    slug: post.slug,
    url: post.url,

    primaryCTA:
      post.primaryCTA || null,

    requiredLinks:
      Array.isArray(post.requiredLinks)
        ? post.requiredLinks.map(link => ({
            url: link.url,
            suggestedAnchor:
              link.url
                .split('/')
                .filter(Boolean)
                .pop()
                ?.replace(/-/g, ' ') || ''
          }))
        : []
  }));

// ------------------------------------------------------------
// FINAL LINK DATABASE FOR AI
// ------------------------------------------------------------

const linkDatabase = {

  // The links REQUIRED for THIS article
  primaryCTA: primaryCTAInfo,

  requiredLinks,

  // Useful validation information
  existingLinks: existingUniqueLinks,

  existingRequiredUrls,

  missingRequiredUrls,

  // Available sibling posts
  relatedPosts
};

// ------------------------------------------------------------
// RETURN
// ------------------------------------------------------------

return [
  {
    json: {

      // ------------------------------------------------------
      // Blog
      // ------------------------------------------------------

      blogContent,

      currentSlug,
      currentTitle,

      // ------------------------------------------------------
      // Current matched post
      // ------------------------------------------------------

      currentPost,

      // ------------------------------------------------------
      // PRIMARY CTA
      // ------------------------------------------------------

      primaryCTA,

      primaryCTAInfo,

      // ------------------------------------------------------
      // DYNAMIC REQUIRED LINKS
      // ------------------------------------------------------

      requiredLinks,

      // Number of required links can now be ANY amount
      requiredLinkCount:
        requiredLinks.length,

      // ------------------------------------------------------
      // Existing links
      // ------------------------------------------------------

      existingLinks:
        existingUniqueLinks,

      existingRequiredUrls,

      missingRequiredUrls,

      // ------------------------------------------------------
      // Other posts
      // ------------------------------------------------------

      otherPosts,

      // ------------------------------------------------------
      // AI database
      // ------------------------------------------------------

      linkDatabaseString:
        JSON.stringify(linkDatabase),

      // ------------------------------------------------------
      // Debug
      // ------------------------------------------------------

      _linkDebug: {

        totalPosts:
          allPosts.length,

        currentPostFound:
          !!currentPost,

        matchMethod,

        matchedSlug:
          currentPost?.slug || null,

        matchedTitle:
          currentPost?.name || null,

        currentSlug,

        currentTitle,

        primaryCTA:
          primaryCTA || null,

        requiredLinkCount:
          requiredLinks.length,

        requiredLinks:
          requiredLinks.map(link => ({
            number: link.number,
            column: link.column,
            url: link.url,
            suggestedAnchor:
              link.suggestedAnchor
          })),

        existingLinkCount:
          existingUniqueLinks.length,

        existingRequiredLinkCount:
          existingRequiredUrls.length,

        missingRequiredLinkCount:
          missingRequiredUrls.length,

        missingRequiredUrls
      }
    }
  }
];

// ============================================================
// Extract Paragraphs
// Purpose: Extract all <p> elements from the content HTML,
//          preserve their inner HTML and attributes, and prepare
//          a numbered plain‑text version for the humanizer step.
// ============================================================

const parsed = $input.first().json;
const html = parsed.content || '';

// Pull out every <p> block (including its inner HTML like <a> tags)
const paragraphs = [];
const pRegex = /<p([^>]*)>([\s\S]*?)<\/p>/gi;
let match;
while ((match = pRegex.exec(html)) !== null) {
  paragraphs.push({
    attrs: match[1],          // preserve any class/id attributes
    innerHtml: match[2],
    plainText: match[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
  });
}

// Build a numbered list of just the plain text for the humanizer
const numberedText = paragraphs
  .map((p, i) => `[P${i}]: ${p.plainText}`)
  .join('\n\n');

return [{
  json: {
    ...parsed,
    _paragraphs: paragraphs,          // original paragraph objects
    _paragraphCount: paragraphs.length,
    _humanizeInput: numberedText      // what we send to the model
  }
}];

const raw = $input.first().json;
let blogRawString = '';

// 1. Extract raw text based on provider format
if (raw?.output?.[0]?.content?.[0]?.text) {
