// 4. HELPER FUNCTIONS
function stripTags(html) {
  return (html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function extractH1(html) {
  if (!html) return { text: null, present: false, containsFocusKeyword: false };
  const h1Match = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);
  if (h1Match) {
    const text = stripTags(h1Match[1]);
    return {
      text: text,
      present: true,
      containsFocusKeyword: text.toLowerCase().includes('map crm data')
    };
  }
  return {
    text: null,
    present: false,
    containsFocusKeyword: false
  };
}

function validateHeadingHierarchy(html) {
  const headings = [];
  const headingRe = /<(h[1-6])[^>]*>([^<]+)<\/h[1-6]>/gi;
  let m;
  while ((m = headingRe.exec(html))) {
    headings.push({
      level: parseInt(m[1]),
      text: stripTags(m[2]),
      tag: m[1]
    });
  }

  const issues = [];
  const warnings = [];

  if (headings.length === 0) {
    issues.push('No headings found in content');
    return { valid: false, headings, issues, warnings };
  }

  if (headings[0].level !== 1) {
    issues.push(`First heading is H${headings[0].level}, should be H1: "${headings[0].text}"`);
  }

  const requiredH2s = [
    'Why CRM Lists Are Hard to Optimize Without Maps',
    'Prerequisites (CRM Fields, Address Quality, Permissions)',
    'Step 1: Clean and Standardize Addresses',
    'Step 2: Geocode Records',
    'Step 3: Plot Accounts and Layer Pipeline Value',
    'Step 4: Overlay Territories and Owners',
    'Step 5: Keep Maps Live with CRM Sync',
    'Common Mistakes (Bad Geocodes, Stale Owners, Filter Spam)',
    'How DotlyMaps Maps CRM Data',
    'FAQ'
  ];

  const h2Headings = headings.filter(h => h.level === 2);
  const h2Texts = h2Headings.map(h => h.text.toLowerCase());

  const missingH2s = [];
  requiredH2s.forEach(required => {
    const requiredLower = required.toLowerCase();
    const found = h2Texts.some(h2 => 
      h2.includes(requiredLower.replace(/[() ,]+/g, ' ').trim()) ||
      requiredLower.includes(h2.split(' ').slice(0, 3).join(' '))
    );
    if (!found) {
      missingH2s.push(required);
    }
  });

  if (missingH2s.length > 0) {
    warnings.push(`Missing required H2 sections: ${missingH2s.join(', ')}`);
  }

  const hasPrereqs = html.toLowerCase().includes('prerequisite') || 
                     html.toLowerCase().includes('checklist') ||
                     html.toLowerCase().includes('required crm fields');
  if (!hasPrereqs) {
    warnings.push('Prerequisites section may be missing the checklist');
  }

  const hasDotlyMaps = html.toLowerCase().includes('dotlymaps') || 
                       html.toLowerCase().includes('dotly maps');
  if (!hasDotlyMaps) {
    warnings.push('DotlyMaps section may be missing');
  }

  const hasDistinction = html.toLowerCase().includes('field mapping') && 
                         html.toLowerCase().includes('geographic');
  if (!hasDistinction) {
    warnings.push('CRM vs field mapping distinction may be missing');
  }

  return {
    valid: issues.length === 0,
    headings,
    issues,
    warnings,
    missingH2s,
    hasPrereqs,
    hasDotlyMaps,
    hasDistinction
  };
}

function validateContentQuality(html) {
  const issues = [];
  const warnings = [];

  const statsRegex = /(\d+%|\d+ percent|\d+\s*percent)/gi;
  const statsMatches = html.match(statsRegex) || [];
  if (statsMatches.length > 0) {
    const hasAttribution = html.toLowerCase().includes('according to') ||
                          html.toLowerCase().includes('study') ||
                          html.toLowerCase().includes('research') ||
                          html.toLowerCase().includes('source') ||
                          html.toLowerCase().includes('report');
    if (!hasAttribution) {
      warnings.push('Found unsubstantiated statistics that should be removed or cited');
    }
  }

  const emDashCount = (html.match(/—/g) || []).length;
  if (emDashCount > 0) {
    warnings.push(`Found ${emDashCount} em dashes which are forbidden`);
  }

  const forbiddenWords = [
    'furthermore', 'moreover', 'additionally', 'in conclusion', 'in summary',
    'leverage', 'delve into', 'game-changer', 'unlock', 'empower', 'streamline'
  ];
  const foundForbidden = [];
  for (const word of forbiddenWords) {
    if (html.toLowerCase().includes(word)) {
      foundForbidden.push(word);
    }
  }
  if (foundForbidden.length > 0) {
    warnings.push(`Found forbidden words: ${foundForbidden.slice(0, 5).join(', ')}`);
  }

  const internalLinks = (html.match(/<a[^>]*href=["'](\/[^"']*)["']/gi) || []);
  const hasCrmMappingLink = internalLinks.some(link => 
    link.includes('/solutions/crm-mapping')
  );
  if (!hasCrmMappingLink) {
    warnings.push('Missing required internal link to /solutions/crm-mapping');
  }

  return {
    issues,
    warnings,
    hasCrmMappingLink,
    emDashCount,
    statsCount: statsMatches.length,
    internalLinksCount: internalLinks.length
  };
}

function validateQuickAnswer(quickAnswer, focusKeyword = 'map crm data') {
  if (!quickAnswer) {
    return { valid: false, issues: ['quickAnswer is empty'], warnings: [] };
  }

  const issues = [];
  const warnings = [];

  if (/^<h[1-6]/i.test(quickAnswer)) {
    issues.push('quickAnswer should be a paragraph, not a heading');
  }

  const wordCount = quickAnswer.split(/\s+/).length;
  if (wordCount < 5) {
    issues.push(`quickAnswer has only ${wordCount} words (should be 2-3 sentences)`);
  } else if (wordCount > 80) {
    warnings.push(`quickAnswer has ${wordCount} words (should be 2-3 sentences)`);
  }

  if (!quickAnswer.toLowerCase().includes(focusKeyword.toLowerCase())) {
    issues.push(`quickAnswer missing focus keyword: "${focusKeyword}"`);
  }

  return {
    valid: issues.length === 0,
    issues,
    warnings,
    wordCount
  };
}

