// ✅ Normalize keyTakeaways to always be [{text: "..."}] objects
function normalizeKeyTakeaways(raw) {
  if (!Array.isArray(raw)) return [];
  return raw
    .map(item => {
      if (typeof item === 'string') return { text: item.trim() };
      if (item && typeof item === 'object') return { text: (item.text || '').trim() };
      return null;
    })
    .filter(item => item && item.text);
}

// ✅ Normalize faq to always be [{question, answer}] objects
function normalizeFaq(raw) {
  if (!Array.isArray(raw)) return [];
  return raw
    .map(item => {
      if (!item || typeof item !== 'object') return null;
      const question = (item.question || '').trim();
      const answer = (item.answer || '').trim();
      if (!question || !answer) return null;
      return { question, answer };
    })
    .filter(Boolean);
}

// ============================================================
// 2. H1 VALIDATION HELPERS
// ============================================================

function extractH1(html) {
  if (!html) return { text: null, present: false, tag: null, warning: null };

  const h1Match = html.match(/<h1[^>]*>\s*([^<]+?)\s*<\/h1>/i);
  if (h1Match) {
    return {
      text: stripTags(h1Match[1]),
      present: true,
      tag: '<h1>',
      warning: null
    };
  }

  const h1CaseMatch = html.match(/<H1[^>]*>\s*([^<]+?)\s*<\/H1>/i);
  if (h1CaseMatch) {
    return {
      text: stripTags(h1CaseMatch[1]),
      present: true,
      tag: '<H1>',
      warning: 'H1 tag should be lowercase'
    };
  }

  return {
    text: null,
    present: false,
    tag: null,
    warning: null
  };
}

function validateHeadingHierarchy(html) {
  const headings = [];
  const headingRe = /<(h[1-6])[^>]*>\s*([^<]+?)\s*<\/h[1-6]>/gi;
  let m;
  while ((m = headingRe.exec(html))) {
    const level = parseInt(m[1].replace('h', ''));
    headings.push({
      level: level,
      text: stripTags(m[2]),
      tag: m[1]
    });
  }

  const issues = [];

  if (headings.length === 0) {
    issues.push('No headings found in content');
    return { valid: false, headings, issues };
  }

  if (headings[0].level !== 1) {
    issues.push(`First heading is H${headings[0].level}, should be H1: "${headings[0].text}"`);
  }

  let expectedLevel = 1;
  for (const h of headings) {
    if (h.level > expectedLevel + 1) {
      issues.push(`Heading level skipped: H${expectedLevel} → H${h.level}: "${h.text}"`);
    }
    expectedLevel = h.level;
  }

  return {
    valid: issues.length === 0,
    headings,
    issues
  };
}

// ============================================================
// 3. DYNAMIC H2 STRUCTURE VALIDATION (based on Outline)
// ============================================================

function validateRequiredH2Structure(html, requiredH2s) {
  if (!requiredH2s || requiredH2s.length === 0) {
    return { valid: true, foundH2s: [], missing: [], missingCount: 0 };
  }

  const h2Re = /<h2[^>]*>\s*([^<]+?)\s*<\/h2>/gi;
  const foundH2s = [];
  let m;
  while ((m = h2Re.exec(html || ''))) {
    foundH2s.push(stripTags(m[1]));
  }

  const missing = [];
  for (const req of requiredH2s) {
    const cleanReq = req.replace(/[^a-zA-Z0-9 ]/g, '').toLowerCase().trim();
    const found = foundH2s.some(h2 => {
      const cleanH2 = h2.replace(/[^a-zA-Z0-9 ]/g, '').toLowerCase().trim();
      return cleanH2.includes(cleanReq) || cleanReq.includes(cleanH2);
    });
    if (!found) missing.push(req);
  }

  return {
    valid: missing.length === 0,
    foundH2s,
    missingCount: missing.length,
    missing
  };
}

