// 4. CONTENT QUALITY CHECKS
// ============================================================

function validateContentQuality(html, faq, quickAnswer, focusKeyword) {
  const issues = [];

  const wordCount = stripTags(html).split(/\s+/).filter(Boolean).length;
  if (wordCount < 1500) {
    issues.push(`Word count is ${wordCount}, below the 1,500 minimum (free model limit)`);
  } else if (wordCount < 3000) {
    issues.push(`Word count is ${wordCount}, below the 3,000 target (free model limitation)`);
  }

  if (html.includes('—')) {
    issues.push('Em dash (—) found in content — voice guidelines forbid this');
  }

  const percentMatches = html.match(/\d{1,3}%/g);
  if (percentMatches && percentMatches.length > 0) {
    issues.push(`Possible invented statistic(s) found: ${percentMatches.join(', ')} — verify these are sourced or reword to directional language`);
  }

  if (faq.length === 0) {
    issues.push('FAQ array is empty');
  }
  if (faq.length < 4) {
    issues.push(`FAQ has only ${faq.length} question(s), needs at least 4`);
  }

  if (!quickAnswer || quickAnswer.length < 20) {
    issues.push('quickAnswer is missing or too short');
  } else if (/^</.test(quickAnswer.trim())) {
    issues.push('quickAnswer appears to contain an HTML tag — should be a plain paragraph');
  } else if (focusKeyword && !quickAnswer.toLowerCase().includes(focusKeyword.toLowerCase())) {
    issues.push(`quickAnswer does not include focus keyword "${focusKeyword}"`);
  }

  const criticalIssues = issues.filter(i =>
    i.includes('empty') ||
    i.includes('missing') ||
    i.includes('does not include focus')
  );

  return {
    valid: criticalIssues.length === 0,
    issues,
    wordCount,
    hasWarnings: issues.length > 0
  };
}

// ============================================================
// 5. MAIN PARSING LOGIC
// ============================================================

const raw = $input.first().json;

// Get blog data from Build Blog Prompt
const buildPromptResult = $('Build Blog Prompt').first().json;
const blog = buildPromptResult.blog || {};
const otherPlatforms = buildPromptResult.otherPlatforms || [];
const focusKeyword = blog['Focus Keyword'] || '';

// ============================================================
// 6. EXTRACT RAW CONTENT
// ============================================================

let blogRawString = '';

if (raw?.output?.[0]?.content?.[0]?.text) {
  blogRawString = raw.output[0].content[0].text;
} else if (raw?.content?.[0]?.text) {
  blogRawString = raw.content[0].text;
} else if (raw?.content?.parts?.[0]?.text) {
  blogRawString = raw.content.parts[0].text;
} else if (raw?.choices?.[0]?.message?.content) {
  blogRawString = raw.choices[0].message.content;
} else if (typeof raw?.text === 'string') {
  blogRawString = raw.text;
} else if (typeof raw === 'string') {
  blogRawString = raw;
}

let cleanJson = blogRawString
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/undefined\??$/, '')
  .trim();

let parsedContent = {};
try {
  parsedContent = JSON.parse(cleanJson);
} catch (e) {
  console.log('⚠️ JSON parsing failed, using fallback');
  parsedContent = {
    title: "Error Parsing Title",
    slug: "error-parsing-slug",
    excerpt: "Error parsing excerpt",
    content: cleanJson,
    metaTitle: "",
    metaDescription: "",
    searchKeywords: []
  };
}

// ============================================================
// 7. H1 EXTRACTION (before stripping) + CONTENT CLEANUP
// ============================================================

// Step 1: Extract H1 from the RAW content before stripping
const rawContentForH1 = parsedContent.content || cleanJson || '';
const h1Info = extractH1(rawContentForH1);

// Step 2: Strip H1 from content so Payload doesn't get a duplicate title
const contentHtml = rawContentForH1
  .replace(/<h1[^>]*>[\s\S]*?<\/h1>/i, '')
  .trim();

// Step 3: Validate heading hierarchy on the STRIPPED content (H2 should now be first)
const hierarchyValidation = validateHeadingHierarchy(contentHtml);

// Build required H2 list from Outline
let requiredH2Titles = [];
const outlineRaw = blog['Outline'] || '';
if (outlineRaw.trim()) {
  requiredH2Titles = outlineRaw.split('|').map(item => item.trim()).filter(Boolean);
}

const h2StructureValidation = validateRequiredH2Structure(contentHtml, requiredH2Titles);

// Step 4: Resolve H1 text — use extracted text, fall back to title field
let h1Text = h1Info.present ? h1Info.text : null;
if (!h1Info.present) {
  h1Text = parsedContent.title || parsedContent.metaTitle || null;
  console.log('⚠️ H1 missing in original content. Using title as fallback:', h1Text);
}

// ============================================================
// 8. EXTRACT SEO FIELDS (with fallbacks)
// ============================================================

const metaTitle = parsedContent.metaTitle || parsedContent.title || '';
const metaDescription = parsedContent.metaDescription || parsedContent.excerpt || '';
const title = h1Text || parsedContent.title || '';

let slug = parsedContent.slug || '';
if (!slug && title) {
  slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

let excerpt = parsedContent.excerpt || '';
if (!excerpt && contentHtml) {
  const pMatch = contentHtml.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
  if (pMatch) {
    excerpt = stripTags(pMatch[1]);
    if (excerpt.length > 160) excerpt = excerpt.slice(0, 157).trim() + '...';
  }
}

let searchKeywords = [];
if (parsedContent.searchKeywords && Array.isArray(parsedContent.searchKeywords)) {
  searchKeywords = parsedContent.searchKeywords;
} else if (parsedContent.searchKeywords && typeof parsedContent.searchKeywords === 'string') {
  searchKeywords = parsedContent.searchKeywords.split(/[,;]/).map(k => k.trim()).filter(Boolean);
} else {
  searchKeywords = [
    focusKeyword || 'CRM data mapping',
    'CRM mapping',
    'territory management',
    'sales analytics',
    'location intelligence'
  ];
}

if (searchKeywords.length < 5) {
  const fallbackKeywords = [
    'CRM data mapping',
    'sales territory management',
    'territory mapping software',
    'location intelligence',
    'CRM analytics dashboard'
  ];
  for (const kw of fallbackKeywords) {
    if (!searchKeywords.includes(kw) && searchKeywords.length < 5) {
      searchKeywords.push(kw);
    }
  }
}
if (searchKeywords.length > 10) searchKeywords = searchKeywords.slice(0, 10);

// ============================================================
// 9. EXTRACT CONTENT FIELDS (with normalization)
// ============================================================

const quickAnswer = parsedContent.quickAnswer || extractQuickAnswer(contentHtml);
const keyTakeaways = normalizeKeyTakeaways(
  (parsedContent.keyTakeaways && parsedContent.keyTakeaways.length)
    ? parsedContent.keyTakeaways
    : extractKeyTakeaways(contentHtml)
);
const faq = normalizeFaq(
  (parsedContent.faq && parsedContent.faq.length)
    ? parsedContent.faq
    : extractFaq(contentHtml)
);

// ============================================================
// 10. VALIDATION & LOGGING
// ============================================================

console.log('=== PARSE BLOG VALIDATION ===');

// H1 check (against original raw content)
if (!h1Info.present) {
  console.log('❌ ERROR: H1 tag was missing from original AI output — using title field as fallback');
} else if (h1Info.warning) {
  console.log('⚠️ H1 warning:', h1Info.warning);
  console.log('   H1 text:', h1Info.text);
} else {
  console.log('✅ H1 found and stripped from content:', h1Info.text);
}

// Heading hierarchy check (on stripped content — H2 should now be first)
if (!hierarchyValidation.valid) {
  console.log('⚠️ Heading hierarchy issues after H1 strip:', hierarchyValidation.issues.join('; '));
  const falsePositive = hierarchyValidation.issues.some(i =>
    i.includes('HNaN') || i.includes('should be H1')
  );
  if (falsePositive) {
    console.log('⚠️ False positive detected in hierarchy check — ignoring');
    hierarchyValidation.valid = true;
    hierarchyValidation.issues = hierarchyValidation.issues.filter(i =>
      !i.includes('HNaN') && !i.includes('should be H1')
    );
  }
} else {
  console.log('✅ Heading hierarchy valid (H2 is now first heading after strip)');
}

// H2 structure check
if (!h2StructureValidation.valid) {
  console.log(`❌ Missing ${h2StructureValidation.missingCount} required H2 section(s):`, h2StructureValidation.missing.join(', '));
  console.log('   H2s found:', h2StructureValidation.foundH2s.join(' | '));
} else {
  console.log('✅ All required H2 sections present');
}

// Content quality check
const contentQuality = validateContentQuality(contentHtml, faq, quickAnswer, focusKeyword);
if (!contentQuality.valid) {
  console.log('❌ Critical content quality issues:', contentQuality.issues.join(' | '));
} else if (contentQuality.hasWarnings) {
  console.log('⚠️ Content quality warnings:', contentQuality.issues.join(' | '));
} else {
  console.log(`✅ Content quality checks passed (${contentQuality.wordCount} words)`);
}

// ============================================================
// 11. BUILD THE RESULT
// ============================================================

return [{
  json: {
    // Core content
    title: title,
    slug: slug,
    excerpt: excerpt,
    content: contentHtml,           // H1 stripped — ready for Payload

    // SEO fields
    metaTitle: metaTitle,
    metaDescription: metaDescription,
    searchKeywords: searchKeywords,

    // Extracted content
    quickAnswer: quickAnswer,
    keyTakeaways: keyTakeaways,
    faq: faq,
    //featuredVideo: 'https://youtu.be/adhGSScoizc',

    // H1 info (from original content, before strip)
    h1: {
      present: h1Info.present,
      text: h1Text,
      tag: h1Info.tag,
      warning: h1Info.warning || null
    },

    // Heading hierarchy (on stripped content)
    headingHierarchy: {
      valid: hierarchyValidation.valid,
      headings: hierarchyValidation.headings,
      issues: hierarchyValidation.issues
    },

    // H2 structure validation
    h2Structure: {
      valid: h2StructureValidation.valid,
      foundH2s: h2StructureValidation.foundH2s,
      missing: h2StructureValidation.missing,
      requiredH2s: requiredH2Titles
    },

    // Content quality
    contentQuality: {
      valid: contentQuality.valid,
      wordCount: contentQuality.wordCount,
      issues: contentQuality.issues,
      hasWarnings: contentQuality.hasWarnings || false
    },

    // Pass-through metadata
    blog: blog,
    otherPlatforms: otherPlatforms,

    // Debug
    _debug: {
      rawLength: blogRawString.length,
      parsedSuccess: !!parsedContent.title,
      metaTitleLength: metaTitle.length,
      metaDescriptionLength: metaDescription.length,
      searchKeywordsCount: searchKeywords.length,
      h1PresentInOriginal: h1Info.present,
      h1Stripped: true,
      headingHierarchyValid: hierarchyValidation.valid,
      h2StructureValid: h2StructureValidation.valid,
      h2StructureMissingCount: h2StructureValidation.missingCount,
      contentQualityValid: contentQuality.valid,
      contentQualityIssueCount: contentQuality.issues.length,
      faqCount: faq.length,
      keyTakeawaysCount: keyTakeaways.length,
      requiredH2Count: requiredH2Titles.length
    }
  }
}];

