// ============================================================
// VALIDATE + NORMALIZE BACKLINKS
// Dynamic per-post required links
// ============================================================

const input = $input.first().json;

// ------------------------------------------------------------
// Extract HTML from OpenAI Responses output
// ------------------------------------------------------------

const html =
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  input.output_text ||
  '';

if (!html || typeof html !== 'string') {
  throw new Error(
    'No HTML returned from Insert Backlinks1.'
  );
}

// ------------------------------------------------------------
// Source data from Input for prompt
// ------------------------------------------------------------

const source =
  $('Input for prompt').first().json || {};

const requiredLinks =
  Array.isArray(source.requiredLinks)
    ? source.requiredLinks
    : [];

const existingLinks =
  Array.isArray(source.existingLinks)
    ? source.existingLinks
    : [];

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function escapeRegex(value) {
  return String(value).replace(
    /[.*+?^${}()|[\]\\]/g,
    '\\$&'
  );
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function countUrl(text, url) {
  return text
    .split(url)
    .length - 1;
}

// ------------------------------------------------------------
// Extract anchor occurrences for a specific URL
// ------------------------------------------------------------

function findAnchorOccurrences(htmlText, url) {

  const escapedUrl =
    escapeRegex(url);

  const regex = new RegExp(
    `<a\\b[^>]*href=["']${escapedUrl}["'][^>]*>([\\s\\S]*?)<\\/a>`,
    'gi'
  );

  const matches = [];

  let match;

  while ((match = regex.exec(htmlText)) !== null) {

    matches.push({
      fullMatch: match[0],
      anchor: match[1],
      index: match.index
    });
  }

  return matches;
}

// ------------------------------------------------------------
// Unwrap one specific anchor occurrence
// Keeps its visible text but removes <a> wrapper.
// ------------------------------------------------------------

function unwrapAnchor(htmlText, fullMatch, anchorText) {
  return htmlText.replace(
    fullMatch,
    anchorText
  );
}

// ------------------------------------------------------------
// Choose best occurrence when duplicate required links exist
//
// Preference:
// 1. Exact suggested anchor
// 2. Same normalized anchor
// 3. First occurrence
// ------------------------------------------------------------

function chooseBestOccurrence(
  occurrences,
  suggestedAnchor
) {

  if (occurrences.length === 0) {
    return null;
  }

  if (!suggestedAnchor) {
    return occurrences[0];
  }

  const target =
    normalizeText(suggestedAnchor);

  const exact =
    occurrences.find(item =>
      normalizeText(
        item.anchor.replace(/<[^>]+>/g, '')
      ) === target
    );

  if (exact) {
    return exact;
  }

  return occurrences[0];
}

// ------------------------------------------------------------
// NORMALIZE REQUIRED LINK DUPLICATES
// ------------------------------------------------------------

let normalizedHtml = html;

const normalizationLog = [];

for (const link of requiredLinks) {

  const url = link.url;

  if (!url) {
    continue;
  }

  const occurrences =
    findAnchorOccurrences(
      normalizedHtml,
      url
    );

  // No linked occurrence.
  // Leave it for validation to report as missing.
  if (occurrences.length === 0) {

    normalizationLog.push({
      url,
      action: 'missing'
    });

    continue;
  }

  // Exactly one occurrence.
  if (occurrences.length === 1) {

    normalizationLog.push({
      url,
      action: 'valid',
      anchor: occurrences[0].anchor
    });

    continue;
  }

  // ----------------------------------------------------------
  // Duplicate occurrences found.
  // Keep the best one, remove wrappers from the others.
  // ----------------------------------------------------------

  const keep =
    chooseBestOccurrence(
      occurrences,
      link.suggestedAnchor
    );

  let removed = 0;

  // Work backwards so indexes remain stable.
  const duplicates =
    occurrences
      .filter(item => item !== keep)
      .sort((a, b) => b.index - a.index);

  for (const duplicate of duplicates) {

    normalizedHtml =
      unwrapAnchor(
        normalizedHtml,
        duplicate.fullMatch,
        duplicate.anchor
      );

    removed++;
  }

  normalizationLog.push({
    url,
    action: 'duplicates_removed',
    keptAnchor: keep.anchor,
    removed
  });
}

// ------------------------------------------------------------
// Extract all final links
// ------------------------------------------------------------

const finalLinks = [
  ...normalizedHtml.matchAll(
    /<a\b[^>]*href=["']([^"']+)["'][^>]*>/gi
  )
].map(match => match[1]);

// ------------------------------------------------------------
// Validate required URLs
// ------------------------------------------------------------

const requiredValidation =
  requiredLinks.map(link => {

    const count =
      countUrl(
        normalizedHtml,
        link.url
      );

    return {
      url: link.url,
      suggestedAnchor:
        link.suggestedAnchor || null,
      count,
      valid: count === 1
    };
  });

const missingRequired =
  requiredValidation.filter(
    item => item.count === 0
  );

const duplicateRequired =
  requiredValidation.filter(
    item => item.count > 1
  );

// ------------------------------------------------------------
// Count every URL
// ------------------------------------------------------------

const urlCounts = {};

for (const url of finalLinks) {

  urlCounts[url] =
    (urlCounts[url] || 0) + 1;
}

const duplicateUrls =
  Object.entries(urlCounts)
    .filter(([url, count]) => count > 1)
    .map(([url, count]) => ({
      url,
      count
    }));

// ------------------------------------------------------------
// Approved URL set
//
// Required URLs + URLs that already existed in source.
// ------------------------------------------------------------

const approvedUrls =
  new Set([
    ...requiredLinks.map(link => link.url),
    ...existingLinks
  ]);

// ------------------------------------------------------------
// External absolute URLs
// ------------------------------------------------------------

const absoluteUrls =
  finalLinks.filter(url =>
    /^https?:\/\//i.test(url)
  );

const unapprovedExternalUrls =
  absoluteUrls.filter(url =>
    !approvedUrls.has(url)
  );

// ------------------------------------------------------------
// Existing source URLs should not be treated as new violations
// ------------------------------------------------------------

const newUrls =
  finalLinks.filter(
    url => !existingLinks.includes(url)
  );

// ------------------------------------------------------------
// Final validity
// ------------------------------------------------------------

const requiredValid =
  requiredValidation.every(
    item => item.count === 1
  );

const valid =
  requiredValid &&
  duplicateRequired.length === 0;

// ------------------------------------------------------------
// Return
// ------------------------------------------------------------

return [
  {
    json: {

      // Preserve all source data
      ...source,

      // IMPORTANT:
      // Return NORMALIZED HTML, not original AI HTML.
      blogContent:
        normalizedHtml,

      linkValidation: {

        valid,

        requiredValid,

        required:
          requiredValidation,

        missingRequiredUrls:
          missingRequired.map(
            item => item.url
          ),

        duplicateRequiredUrls:
          duplicateRequired.map(
            item => ({
              url: item.url,
              count: item.count
            })
          ),

        duplicateUrls,

        unapprovedExternalUrls,

        totalLinks:
          finalLinks.length,

        uniqueLinks:
          [...new Set(finalLinks)].length,

        newUrls,

        normalizationLog
      },

      _linkDebug: {

        requiredLinkCount:
          requiredLinks.length,

        requiredLinks:
          requiredLinks.map(link => ({
            url: link.url,
            suggestedAnchor:
              link.suggestedAnchor || null
          })),

        existingLinkCount:
          existingLinks.length,

        finalLinkCount:
          finalLinks.length,

        finalUniqueLinkCount:
          [...new Set(finalLinks)].length,

        requiredValid,

        missingRequiredCount:
          missingRequired.length,

        duplicateRequiredCount:
          duplicateRequired.length
      }
    }
  }
];
